// Shared by the book editor, opening and explicit roster initialization.
function xzInitialKey(source,name){return encodeURIComponent(source)+':'+encodeURIComponent(name);}
function xzInitialStore(){
    const c=(globalThis.parent?.SillyTavern||globalThis.SillyTavern).getContext(),ch=c.characters?.[c.characterId];
    const value=ch?.data?.extensions?.xz_initial_data;
    if(value===undefined)return {v:1,bookId:ch?.data?.extensions?.canon?.bookId||'xianzi',items:{}};
    if(value.v!==1||value.bookId!==(ch?.data?.extensions?.canon?.bookId||'xianzi')||!value.items||typeof value.items!=='object'||Array.isArray(value.items))throw Error('本书人物初始数据配置异常，请先导出保留');
    return value;
}
function xzInitialRow(source,name,base,people=typeof XZ_INITIAL_PEOPLE!=='undefined'?XZ_INITIAL_PEOPLE:null){
    const patch=xzInitialStore().items[xzInitialKey(source,name)]??{};
    if(!patch||typeof patch!=='object'||Array.isArray(patch))throw Error('人物初始数据损坏，请先检查配置');
    const unified=people!==null&&source!=='relations'&&name!=='@player';
    const basic=unified?{...xzInitialBasic(people[name]||{}),...xzInitialBasic(xzInitialStore().items[xzInitialKey('custom',name)]||{})}:{};
    return JSON.parse(JSON.stringify({...base,...patch,...basic}));
}
function xzInitialStat(stat,source,player=true,people=typeof XZ_INITIAL_PEOPLE!=='undefined'?XZ_INITIAL_PEOPLE:null){
    const next=JSON.parse(JSON.stringify(stat));
    for(const [name,row]of Object.entries(next.角色名册||{}))next.角色名册[name]=xzInitialRow(source,name,row,people);
    if(player&&next.玩家)next.玩家=xzInitialRow(source,'@player',next.玩家,people);
    return next;
}
function xzInitialOpening(data){
    for(const [key,stat]of Object.entries(data.presetVars))data.presetVars[key]=xzInitialStat(stat,key);
    for(const scene of data.presets)scene.player=xzInitialRow(String(scene.gi),'@player',scene.player);
}
function xzInitialAgeRule(name,stat,source){
    const patch=typeof XZ_INITIAL_PEOPLE!=='undefined'?xzInitialRow('custom',name,XZ_INITIAL_PEOPLE[name]||{}):xzInitialStore().items[xzInitialKey(source,name)]||{};
    if(!Object.hasOwn(patch,'年龄')&&!(source==='default'&&Object.hasOwn(patch,'年龄规则')))return null;
    if(!Object.hasOwn(patch,'年龄')&&patch.年龄规则?.固定年龄!==''){
        const fixed=Number(patch.年龄规则?.固定年龄);if(Number.isInteger(fixed)&&fixed>0)return {fixed};
    }
    const value=String(stat.角色名册?.[name]?.年龄||''),age=/^(\d+)岁?$/.exec(value),year=/^(\d{4})-/.exec(String(stat.系统?.纪元时刻||''));
    return age&&year?{born:Number(year[1])-Number(age[1])}:{unknown:true};
}
function xzInitialAges(stat,source){
    const out={v:1,bookId:xzInitialStore().bookId,people:{}};
    for(const name of Object.keys(stat.角色名册||{})){const rule=xzInitialAgeRule(name,stat,source);if(rule)out.people[name]=rule;}
    return out;
}
function xzInitialRememberAge(vars,name,stat){
    const rule=xzInitialAgeRule(name,stat,'default');if(!rule)return;
    const bookId=xzInitialStore().bookId;
    if(vars.xz_initial_ages?.v!==1||vars.xz_initial_ages.bookId!==bookId)vars.xz_initial_ages={v:1,bookId,people:{}};
    vars.xz_initial_ages.people[name]=rule;
}

function xzInitialBasic(row){return Object.fromEntries(Object.entries(row).filter(([k])=>['身份','姓名','性别','年龄','当前境界','出身','定位','生死'].includes(k)));}
function xzInitialRelations(base){
    const out=JSON.parse(JSON.stringify(base));
    for(const [id,patch]of Object.entries(xzInitialStore().items)){
        if(!id.startsWith('relations:'))continue;
        const name=decodeURIComponent(id.slice(10));
        if(patch?.关系&&typeof patch.关系==='object'&&!Array.isArray(patch.关系))out[name]=JSON.parse(JSON.stringify(patch.关系));
    }
    return out;
}
function xzInitialRelationStat(stat,base,role="",player=""){
    const background=xzInitialRelations(base),existing=stat.关系||{},out={},roster=stat.角色名册||{};
    for(const [s,edges]of Object.entries(background))for(const [target,edge]of Object.entries(edges)){
        const o=role&&player&&target===role?player:target;
        if(s===role||s===player||!roster[s]||(!roster[o]&&o!==player))continue;
        if(!existing[s]?.[o]&&!(roster[s].是否在场&&(o===player||roster[o]?.是否在场)))continue;
        (out[s]??={})[o]={...existing[s]?.[o],...JSON.parse(JSON.stringify(edge))};
    }
    stat.关系=out;
}

// Initialization templates belong to one card/book, never the global account.
function installInitialDataManager(catalog){
    const ctx=()=>window.SillyTavern.getContext(),card=()=>ctx().characters?.[ctx().characterId],owner=card()?.avatar;
    if(window.XZ_INITIAL_DATA){window.XZ_INITIAL_DATA.register(owner,catalog);return;}
    const catalogs=new Map([[owner,catalog]]),KEY='xz_initial_data';let busy=false;
    const copy=x=>JSON.parse(JSON.stringify(x));
    const equal=(a,b)=>a===b||!!a&&!!b&&typeof a==='object'&&typeof b==='object'&&Array.isArray(a)===Array.isArray(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&equal(a[k],b[k]));
    function delta(before,after){if(!after||typeof after!=='object'||Array.isArray(after))return copy(after);const out={};for(const k of Object.keys(before||{}))if(!Object.hasOwn(after,k))out[k]='__@@UNSET@@__';for(const [k,v]of Object.entries(after))out[k]=delta(before?.[k],v);return out;}
    function scope(bookId){const c=ctx(),cat=catalogs.get(card()?.avatar);if(c.groupId||!cat||!card()||(bookId!==undefined&&bookId!==cat.bookId)||(card().data.extensions.canon?.bookId||'xianzi')!==cat.bookId)throw Error('本书尚未提供独立人物初始化模板');return {avatar:card().avatar,book:cat.bookId,chat:c.chatId};}
    function check(s){const n=scope(s.book);if(n.avatar!==s.avatar||n.chat!==s.chat)throw Error('书籍或聊天已切换，操作已停止');}
    const data=()=>catalogs.get(card()?.avatar);
    const config=()=>xzInitialStore();
    function list(bookId){scope(bookId);return copy(data().rows).map(row=>({...row,value:xzInitialRow(row.source,row.name,row.data,data().people||null),custom:Object.hasOwn(config().items,row.id)}));}
    function validate(value,base){
        if(!value||typeof value!=='object'||Array.isArray(value))throw Error('人物初值必须为对象');
        if(JSON.stringify(value).length>80000)throw Error('单个人物初值最多 80000 字符');
        function walk(v,b){
            if(v===null){if(b===undefined||b===null)return;throw Error('请保留字段原有类型');}
            if(!['string','number','boolean','object'].includes(typeof v))throw Error('不支持的字段类型');
            if(b===null&&(typeof v!=='object'||Array.isArray(v)))throw Error('此字段应为对象或 null');
            if(typeof v==='number'&&!Number.isFinite(v))throw Error('数字必须有效');
            if(typeof v==='string'&&v==='__@@UNSET@@__')throw Error('此内容为系统保留标记');
            if(b!==undefined&&b!==null&&(typeof v!==typeof b||Array.isArray(v)!==Array.isArray(b)))throw Error('请保留字段原有类型');
            if(v&&typeof v==='object')for(const [k,x]of Object.entries(v)){if(['__proto__','constructor','prototype'].includes(k))throw Error('字段名称不受支持');walk(x,b?.[k]);}
        }
        walk(value,base);
        for(const k of Object.keys(base))if(!Object.hasOwn(value,k))throw Error('请保留字段：'+k);
        if(value.年龄规则){const a=value.年龄规则;for(const k of ['基准年龄','基准年份','固定年龄'])if(a[k]!==''&&(!Number.isInteger(Number(a[k]))||(k!=='基准年份'&&Number(a[k])<1)))throw Error('年龄规则需填写整数，留空表示不指定');}
    }
    async function disk(s){const r=await fetch('/api/characters/get',{method:'POST',headers:ctx().getRequestHeaders(),body:JSON.stringify({avatar_url:s.avatar})});if(!r.ok)throw Error('读取角色卡失败');const v=await r.json();return v.json_data?JSON.parse(v.json_data):v;}
    function plain(v){if(v===undefined)return {v:1,bookId:scope().book,items:{}};return v;}
    function updateMemory(next){
        card().data.extensions[KEY]=copy(next);
        if(card().json_data){const raw=JSON.parse(card().json_data);raw.data.extensions[KEY]=copy(next);card().json_data=JSON.stringify(raw);const input=document.getElementById('character_json_data');if(input)input.value=card().json_data;}
    }
    async function reload(s){if(busy)throw Error('正在保存，请稍候');check(s);const before=copy(config()),server=await disk(s);check(s);if(!equal(config(),before))throw Error('页面配置同时变化，请重试');const next=plain(server.data.extensions[KEY]);if(next.v!==1||next.bookId!==s.book||!next.items||typeof next.items!=='object'||Array.isArray(next.items))throw Error('服务器人物初始化配置异常');updateMemory(next);}
    async function save(id,value,expected,s,mode='one'){
        if(busy)throw Error('正在保存，请稍候');check(s);
        const row=list(s.book).find(r=>r.id===id);if(!row)throw Error('人物条目不存在');
        if(!equal(row.value,expected))throw Error('此人物已被另一面板修改，请保留草稿并重读');
        const checked=mode==='reset'?row.data:value;
        if(mode!=='reset'&&row.source==='custom'){
            if(checked.年龄!==row.value.年龄&&checked.年龄!==undefined&&checked.年龄!==''&&!/^[0-9]+$/.test(String(checked.年龄)))throw Error('年龄只能填写阿拉伯数字（0–9）');
            if(data().realms&&checked.当前境界!==row.value.当前境界&&!data().realms.includes(checked.当前境界))throw Error('请选择有效的当前境界');
        }
        validate(checked,row.data);
        if(row.source==='relations'){
            const names=new Set(data().rows.filter(r=>r.source==='custom').map(r=>r.name));
            for(const [name,edge]of Object.entries(checked.关系||{})){
                if(name===row.name||!names.has(name))throw Error('关系对象必须是本书的另一位人物');
                if(!edge||typeof edge!=='object'||typeof edge.关系!=='string'||!edge.关系.trim())throw Error('请填写关系名称');
                if(!['血亲','姻亲','夫妻','师徒','同门','上下属','情愫','交情','仇怨'].includes(edge.类别))throw Error('请选择有效的关系类别');
                for(const key of ['称呼','自称'])if(edge[key]!==undefined&&(!Array.isArray(edge[key])||edge[key].some(x=>!x||typeof x.场景!=='string'||typeof x[key]!=='string')))throw Error(key+'需填写场景与内容');
            }
        }
        if(mode==='all'&&(row.name==='@player'||Object.hasOwn(value,'年龄规则')&&!equal(value.年龄规则,row.value.年龄规则)))throw Error('主角和补录年龄规则请在各自来源单独保存');
        busy=true;
        try{
            const before=copy(config()),server=await disk(s);check(s);
            if(!equal(plain(server.data.extensions[KEY]),before)||!equal(config(),before))throw Error('服务器配置已变化，请保留草稿并重读');
            const next=copy(before),patches={},changes=Object.fromEntries(Object.entries(value).filter(([k,v])=>!equal(v,row.value[k])));
            const targets=mode==='all'?list(s.book).filter(r=>r.name===row.name):[row];
            for(const target of targets){
                const desired=mode==='reset'?(target.source==='custom'?{...target.value,...xzInitialBasic(target.data)}:target.data):mode==='all'?{...target.value,...changes}:value;
                validate(desired,target.data);
                const patch=Object.fromEntries(Object.entries(desired).filter(([k,v])=>!equal(v,target.data[k])));
                if(Object.keys(patch).length)next.items[target.id]=patch;else delete next.items[target.id];
                // Replace the changed row using deletion markers for removed overrides.
                patches[target.id]=Object.keys(patch).length?delta(before.items[target.id],patch):'__@@UNSET@@__';
            }
            const response=await fetch('/api/characters/merge-attributes',{method:'POST',headers:ctx().getRequestHeaders(),body:JSON.stringify({avatars:[s.avatar],data:{data:{extensions:{[KEY]:{v:1,bookId:s.book,items:patches}}}}})});
            if(!response.ok)throw Error('服务器未能保存，草稿已保留');const result=await response.json();if(!result.updated?.includes(s.avatar))throw Error('服务器未确认保存');check(s);
            const after=await disk(s);check(s);if(!equal(after.data.extensions[KEY],next))throw Error('保存回读不一致，请保留草稿并重读');
            if(!equal(config(),before))throw Error('保存期间页面配置变化，请重读确认');
            updateMemory(next);
            window.dispatchEvent(new CustomEvent('xz-initial-data'));return targets.length;
        }finally{busy=false;}
    }
    function world(template){scope(template.bookId);const out=copy(template.world);if(!template.initialData)return out;
        const entry=Object.values(out.entries).find(e=>e.comment===template.initialComment);if(!entry)throw Error('本书缺少初始化世界书条目');
        const initial=copy(template.initialData);
        for(const [name,row]of Object.entries(data().people||{}))initial.角色名册[name]={...copy(row),...initial.角色名册[name]};
        for(const row of data().rows.filter(r=>r.source==='world'&&r.name!=='@player'))if(Object.hasOwn(config().items,row.id)&&!Object.hasOwn(initial.角色名册,row.name))initial.角色名册[row.name]=copy(row.data);
        if(data().relations)xzInitialRelationStat(initial,data().relations);
        entry.content=JSON.stringify(xzInitialStat(initial,'world',true,data().people||null),null,2);return out;
    }
    window.XZ_INITIAL_DATA={version:1,realms:()=>copy(data().realms||[]),scope,list,save,reload,world,config:()=>copy(config()),register:(avatar,cat)=>catalogs.set(avatar,cat),get busy(){return busy;}};
}

