    // Edit prose in the bound native worldbook, retaining entry identity and triggers.
function installWorldbookManager(catalog = {}) {
    const ctx = () => window.SillyTavern.getContext();
    const owner=()=>ctx().characters?.[ctx().characterId]?.avatar;
    if (window.XZ_WORLDBOOK) { window.XZ_WORLDBOOK.register(owner(),catalog); return; }
    const catalogs=new Map([[owner(),catalog]]);
    const copy = value => JSON.parse(JSON.stringify(value));
    const equal = (a,b) => a===b || !!a&&!!b&&typeof a==='object'&&typeof b==='object'&&Array.isArray(a)===Array.isArray(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&equal(a[k],b[k]));
    let busy = false;
    function category(entry) {
        const title = entry.comment || '';
        const known=catalogs.get(owner())?.entries?.[title];
        if(known) return known;
        if (/^(女主|女配|男主|男配|苦主|黄毛)·/.test(title)) return {kind:'persona',group:title.split('·')[0]};
        if (title==='角色速览') return {kind:'persona',group:'人物总览'};
        if (title==='世界观') return {kind:'world',group:'世界设定'};
        if (title==='境界与修行') return {kind:'world',group:'修行体系'};
        if (/^(势力|地点|丹药|功法|器物|灵根|术语)·/.test(title)) return {kind:'world',group:title.split('·')[0]};
        if (title==='故事纲领以及走向大纲') return {kind:'world',group:'故事纲领'};
        return null;
    }
    function scope(bookId) {
        const c=ctx(),ch=c.characters?.[c.characterId];
        if(c.groupId||!ch||bookId!==(ch.data.extensions.canon?.bookId||'xianzi')) throw Error('请先打开本书的单人聊天');
        const active=window.XZ_SAVE_MANAGER?.active();
        const world=active?.world||ch.data.extensions.world;
        if(!world) throw Error('本书尚未绑定可编辑的世界书');
        return {avatar:ch.avatar,chat:c.chatId,bookId,world,saved:!!active,localId:active?.localId||'',runtimeId:active?.id||''};
    }
    function check(s) { if(!equal(scope(s.bookId),s)) throw Error('书籍、聊天或世界书已切换，请重新打开'); }
    async function disk(name) {
        const response=await fetch('/api/worldinfo/get',{method:'POST',headers:ctx().getRequestHeaders(),body:JSON.stringify({name}),cache:'no-store'});
        if(!response.ok) throw Error('读取世界书失败，请重试');
        const value=await response.json();
        if(!value?.entries||typeof value.entries!=='object'||Array.isArray(value.entries)) throw Error('世界书内容异常');
        return value;
    }
    async function list(bookId) {
        const s=scope(bookId),world=await disk(s.world);check(s);
        return {scope:s,rows:Object.entries(world.entries).flatMap(([id,entry])=>{const cat=category(entry);return cat?[{id,...cat,title:entry.comment,entry:copy(entry)}]:[]})};
    }
    async function save(s,id,content,expected) {
        if(busy) throw Error('正在保存，请稍候');
        check(s);
        if(typeof content!=='string'||!content.trim()) throw Error('请填写条目内容');
        if(content.length>200000) throw Error('单条内容最多 200000 字符');
        busy=true;
        try {
            const world=await disk(s.world);check(s);
            const entry=world.entries[id];
            if(!entry||!category(entry)||!equal(entry,expected)) throw Error('此条目已在别处修改，请先复制草稿，再重新读取');
            const cached=await ctx().loadWorldInfo(s.world);check(s);
            if(!equal(cached?.entries,world.entries)) throw Error('世界书有其他未同步改动，请稍后重试或刷新页面；草稿已保留');
            const next=copy(world);next.entries[id].content=content;
            await ctx().saveWorldInfo(s.world,next,true);check(s);
            const saved=await disk(s.world);check(s);
            if(!equal(saved.entries,next.entries)) throw Error('保存回读不一致，请保留草稿并重新读取核对');
            return copy(saved.entries[id]);
        } finally { busy=false; }
    }
    // New saves inherit the card's current prose, while runtime/init entries
    // still come from the immutable template and initialization editor.
    async function initialWorld(bookId,template) {
        const ch=ctx().characters[ctx().characterId],name=ch?.data.extensions.world;
        if(ctx().groupId||!ch||bookId!==(ch.data.extensions.canon?.bookId||'xianzi')) throw Error('请先打开本书的单人聊天');
        const result=copy(template);
        if(!name) return result;
        const s=scope(bookId);
        const source=await disk(name);check(s);
        const entries=Object.values(source.entries);
        for(const entry of Object.values(result.entries)) if(category(entry)) {
            const current=entries.find(e=>e.comment===entry.comment);
            if(current) entry.content=current.content;
        }
        return result;
    }
    window.XZ_WORLDBOOK={scope,list,save,initialWorld,category,register:(avatar,value)=>catalogs.set(avatar,value),get busy(){return busy;}};
}

