            const next=copy(before);if(reset&&!e.point)delete next.items[id];else next.items[id]=text;
            // Native writeExtensionField can optimistically mutate memory even
            // when its HTTP write fails. Commit one key, then refresh memory.
            const response=await fetch('/api/characters/merge-attributes',{method:'POST',headers:ctx().getRequestHeaders(),body:JSON.stringify({avatars:[s.avatar],data:{data:{extensions:{[KEY]:{v:1,items:{[id]:reset&&!e.point?'__@@UNSET@@__':text}}}}}})});
            if(!response.ok)throw Error('服务器未能保存，草稿仍保留');
            const result=await response.json();if(!result.updated?.includes(s.avatar))throw Error('服务器未确认角色卡更新');check(s);
            const after=await disk(s);check(s);
            if(!equal(after.data.extensions[KEY],next))throw Error('尚未确认保存成功，请保留草稿并重试');
