    function scope(){const c=ctx(),ch=c.characters?.[c.characterId];if(c.groupId||!c.chatId||!ch?.data?.extensions?.canon)throw Error('请先打开本书的单人聊天');return {avatar:ch.avatar,chat:c.chatId,book:ch.data.extensions.canon.bookId||'xianzi',...(c.chatMetadata?.xz_book_save?.localId?{save:c.chatMetadata.xz_book_save.localId}:{})};}
