    // Rebase only automatically generated opening prehistory, in one checked write.
    async function reviseOpening(plan,expected,{preview=false}={}){return exclusive(async()=>{
        const s=scope(),before=read(),key='xz-opening:'+s.book+':main';
        if(ctx().chat.length!==1)throw Error('已有后续剧情，不能修改开局前情');
        if(!equal(before,expected))throw Error('开局纪要已被其他操作修改，请重新核对');
        if(plan!==null&&(plan?.key!==key||!plan.table))throw Error('开局前情不属于当前书籍');
        const owned=r=>r.source?.kind==='database'&&r.source.key?.startsWith(key+'\0');
        const old=before.records.filter(owned);
        // A marked edit is protected even if its current text happens to match.
        if(old.some(r=>r.editedAt||core.fields.some(f=>String(r[f]||'')!==String(r.source.raw?.[f]||''))))
            throw Error('原著前情中有手动修改的纪要，已保留；请先导出并处理这些条目，或新建存档后修改节点');
        const next=copy(before);next.records=next.records.filter(r=>!owned(r));
        let result=null;
        if(plan){result=core.migrate({[key]:plan.table},key,{code:'code',time:'time',summary:'summary',text:'text',dialogue:'dialogue'},next.records);}
        if(preview)return {removed:old.length,added:result?.records.length||0};
        const now=Date.now();
        if(result?.records.length){next.records.push(...result.records.map(r=>({...r,id:uuid(),createdAt:now})));next.imports.push({id:uuid(),at:now,table:result.table.name,mapping:{code:'code',time:'time',summary:'summary',text:'text',dialogue:'dialogue'},raw:result.table.raw});}
        await commit(next,before,s,()=>{if(ctx().chat.length!==1)throw Error('已有后续剧情，不能修改开局前情');});
        return {removed:old.length,added:result?.records.length||0};
    });}
