        const c=ctx(),character=c.characters?.[c.characterId],background={persona:c.powerUserSettings?.persona_description||'',character:character?.description||character?.data?.description||''};
        let crossfire;try{crossfire=window.XZ_CROSSFIRE?.snapshot();}catch(e){throw Error('交火配置：'+e.message);}
        const routes=[{id:'current',label:'本局记忆',records,config:settings,profile,prompt,background,crossfire}];
