        for(const m of data.messages||[]){if(typeof m.content==='string')m.content=strip(m.content,m);else if(Array.isArray(m.content))for(const part of m.content)if(part.type==='text'&&typeof part.text==='string')part.text=strip(part.text,m);}
        if(found){auxRequests.add(data);data.messages=data.messages.filter(m=>!changed.has(m)||m.role!=='system'||(typeof m.content==='string'?m.content.trim():m.content.some(p=>p.type!=='text'||p.text.trim())));}
