            let settled=false;
            const req=indexedDB.open('xz_crossfire_v1',2);
            const clearBlocked=()=>{if(blockedOpen===req)blockedOpen=null;};
            const fail=error=>{if(!settled){settled=true;reject(error);}};
            req.onblocked=()=>{blockedOpen=req;fail(Error('交火索引升级被其他页面占用，请关闭旧页面后重试'));};
