            const handle=await db(),legacy=await new Promise((resolve,reject)=>{const req=handle.transaction('vectors','readonly').objectStore('vectors').getAll();req.onsuccess=()=>resolve(req.result.filter(r=>!r.archiveScope));req.onerror=()=>reject(Error('无法读取旧交火索引'));});
