            for(const candidate of scopes)for(const dimension of dimensions){const keys=await Promise.all(records.map(r=>digest([account,candidate,profile.id,profile.url,profile.model,dimension,source(r)]))),values=await cache(keys);values.forEach((v,i)=>{if(v)add({providerHash,model:profile.model,sourceHash:hashes[i],vector:v});});}
