    function vector(v){if(!Array.isArray(v)||!v.length||v.some(n=>typeof n!=='number'||!Number.isFinite(n)))throw Error('向量接口返回无效向量');const norm=Math.hypot(...v);if(!Number.isFinite(norm)||!norm)throw Error('向量长度无效');return v.map(n=>n/norm);}
