// Saved defaults are frozen with the chat; changing a book template cannot rewrite an old save.
function xdInitialBackground(){
    try{
        const c=SillyTavern.getContext(),book=c.characters?.[c.characterId]?.data?.extensions?.canon?.bookId||'xianzi';
        const saved=TavernHelper.getVariables({type:'chat'})?.xz_initial_relations;
        if(saved?.v===1&&saved.bookId===book&&saved.people&&typeof saved.people==='object'&&!Array.isArray(saved.people))return saved.people;
    }catch{}
    return XD_BG;
}

