  const avatar = initialCharacter && initialCharacter.avatar;
  if (!avatar || initial.groupId || !initialCharacter.data?.extensions?.canon) return;
  if (host[NAME]) { host[NAME].register(avatar); return; }
  const allowed = new Set([avatar]);
