    + ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("canon-inject.js:clockBlock.008598a62471",[xxFromMin(p.waiting.from),p.waiting.event.title,xxFromMin(p.waiting.at)]) ?? (`当前 ${xxFromMin(p.waiting.from)}；下一事件〔${p.waiting.event.title}〕安排在 ${xxFromMin(p.waiting.at)}。\n`))
