// 开局之前就死了的原著人物（roster_all.DEAD）：「死了」不算登场过（跟 roster-seen.js 的 RS_CANON_DEAD 一样）
const XD_CANON_DEAD = ["宋思"];
// chat 变量（跟着聊天走，不随楼层回滚）：登场过（名册界面和这里都往里记）、已删除（名册 × / 关系图「移除」记）、
// 扮演（开局器记：玩家顶替的原著人物的名册键，背景表里写的是这个名字）
const XD_SEEN_KEY = '登场过', XD_DEL_KEY = '已删除', XD_ROLE_KEY = '扮演';
const XD_SCENE = ['当前姿势', '当前行为', '当前服装', '身体状态', '情境概括'];
const XD_REL_ID = 'canon_relations';
const XD_ME_ID = 'xianzi_player_state';

function xdObj(v) { return !!v && typeof v === 'object' && !Array.isArray(v); }
function xdTxt(v) { return v == null ? '' : String(v).trim(); }
function xdHas(o, k) { return Object.prototype.hasOwnProperty.call(o, k); }

/** 主角名。开局前是「未定」，当作认不出 */
function xdPlayerName(stat) {
  const n = xdTxt(stat && xdObj(stat.玩家) ? stat.玩家.姓名 : '');
  return n && n !== '未定' ? n : '';
}

/** 一条边错在哪；空串 = 没错。me 为空（认不出主角）时不查「端点不在名册」 */
function xdEdgeWhy(s, o, e, inRoster, me) {
  if (!xdObj(e)) return '不是一条关系';
  if (o === s) return '自己对自己';
  if (me && !inRoster(o) && o !== me) return '客体不在名册里';
  return '';
}

/* ---------- 懒加载：背景关系等人登场了才进 stat_data（2026-09-25 用户定） ----------
 * 「关系只有等初始化后才发出去，如果人物未初始化就不发送。只发送展示的部分，如果玩家删除某个节点了就不许发送了。」
 *
 *  初始化 = 登场过，跟名册「只列登场过的人」同一个判据（src/roster-seen.js 的 rsOnStage / rsCounts）：
 *    在场；死了（开局前就死的除外）；在 chat 变量「登场过」里；不在原著名单里（AI 新建的）；
 *    有一条写了最近一次交互的关系（背景边也算）。主角永远算已初始化。
 *  已删除 = chat 变量「已删除」（玩家在名册点 ×、在关系图点「移除」记进去，「恢复」拿掉）。名单里的人：
 *    背景边不补、stat_data.关系 里涉及他的边清掉——AI 之后把他重新写回名册也一样（用户：删除了就不许发送）。
 *
 *  xdBgFill（mag_variable_update_ended，清理之后）：两端都已初始化（客体也可以是主角）、都没删、变量里还没有的背景边补进去，
 *    称呼照表，自称按这一刻的纪元时刻取原著表；已经在变量里的边不覆盖（AI 改过的算数）。
 *  清理（xdCleanRelations）：已删除的人的边删掉；背景边（键在 XD_BG 里、最近一次交互还空着）有一端没初始化的删掉——
 *    老存档里整本铺进去的两百多条背景关系按新规矩收掉；AI 写过最近一次交互的、不在背景表里的边一律不动。
 *  补进去的边在楼层变量里，随楼层回滚：删楼 / swipe 之后下一次更新按回滚后的状态重新判定。
 *  chat 变量读不出来（离线、酒馆还没起来）：不补、也不按「没初始化」删——认不出就不动。 */

/** chat 变量里的三样。读不出来 ok = false */
function xdChatCtx() {
  const none = { ok: false, seen: [], del: [], role: '' };
  try {
    if (typeof TavernHelper === 'undefined' || typeof TavernHelper.getVariables !== 'function') return none;
    const v = TavernHelper.getVariables({ type: 'chat' });
    if (!xdObj(v)) return none;
    const arr = x => (Array.isArray(x) ? x.map(xdTxt).filter(Boolean) : []);
    // 「已删除」一项是名字（老写法）或者 {名字, 名册}（名册 = 删之前那一格，恢复时界面放回去）
    const del = (Array.isArray(v[XD_DEL_KEY]) ? v[XD_DEL_KEY] : []).map(x => xdTxt(xdObj(x) ? x.名字 : x)).filter(Boolean);
    return { ok: true, seen: arr(v[XD_SEEN_KEY]), del: del, role: xdTxt(v[XD_ROLE_KEY]) };
  } catch (e) { return none; }
}

/** s → o 是不是一条背景边。o 是主角时按他顶替的原著人物（role）查 */
function xdBgOf(s, o, me, role) {
  const background=xdInitialBackground();
  const row = xdObj(background) && xdHas(background, s) && xdObj(background[s]) ? background[s] : null;
  if (!row) return null;
  if (xdHas(row, o) && xdObj(row[o])) return row[o];
  if (me && role && o === me && role !== me && xdHas(row, role) && xdObj(row[role])) return row[role];
  return null;
}

/** 名册里算已初始化（登场过）的人，Set。不含主角（他永远算，调用处自己加）；已删除的人不算 */
function xdInited(stat, ctx) {
  const out = new Set();
  const r = xdObj(stat) && xdObj(stat.角色名册) ? stat.角色名册 : {};
  const rel = xdObj(stat) && xdObj(stat.关系) ? stat.关系 : {};
  const me = xdPlayerName(stat);
  const seen = new Set(ctx.seen), del = new Set(ctx.del), dead = new Set(XD_CANON_DEAD), canon = new Set(XD_CANON);
  const linked = new Set();
  Object.keys(rel).forEach(s => {
    if (!xdObj(rel[s])) return;
    Object.keys(rel[s]).forEach(o => {
      const e = rel[s][o];
      // 写了最近一次交互的边（背景边也算：AI 在它上面写了一笔，说明两人已经在剧情里碰上了）
      if (xdObj(e) && xdTxt(e.最近一次交互)) { linked.add(s); linked.add(o); }
    });
  });
  Object.keys(r).forEach(k => {
    const p = r[k];
    if (!xdObj(p) || del.has(k)) return;
    if (p.是否在场 === true || (xdTxt(p.生死) === '死' && !dead.has(k)) || seen.has(k)
        || (canon.size && !canon.has(k)) || linked.has(k)) out.add(k);
  });
  return out;
}

/** 把两端都已初始化、都没删、变量里还没有的背景边补进 stat_data.关系，返回日志。now = 纪元时刻的分钟（取自称用） */
function xdBgFill(stat, ctx, now) {
  const background=xdInitialBackground();
  const log = [];
  if (!ctx || !ctx.ok || !xdObj(stat)) return log;
  const r = xdObj(stat.角色名册) ? stat.角色名册 : {};
  const me = xdPlayerName(stat), role = ctx.role;
  const inited = xdInited(stat, ctx), del = new Set(ctx.del);
  const ok = n => (n === me && !!me) || (inited.has(n) && xdHas(r, n));
  const added = [];
  Object.keys(background || {}).forEach(s => {
    if (!xdObj(background[s]) || s === me || (role && s === role) || !inited.has(s) || !xdHas(r, s)) return;
    Object.keys(background[s]).forEach(o0 => {
      const o = me && role && o0 === role ? me : o0;           // 背景表写的是原著名字，玩家顶替了他就换成主角姓名
      if (o === s || del.has(o) || del.has(s) || !ok(o)) return;
      if (!xdObj(stat.关系)) stat.关系 = {};
      if (xdObj(stat.关系[s]) && xdHas(stat.关系[s], o)) return;    // 已经有了：AI 改过的算数，不覆盖
      const b = background[s][o0], e = { 关系: xdTxt(b.关系), 类别: b.类别 };
      const addr = xdSays(b.称呼, '称呼'), self = Object.hasOwn(b,'自称') ? xdSays(b.自称,'自称') : xdCanonSelf(XD_SELF, s, o0, now);
      if (addr.length) e.称呼 = addr;
      if (self.length) e.自称 = self;
      if (!xdObj(stat.关系[s])) stat.关系[s] = {};
      stat.关系[s][o] = e;
      added.push(s + ' → ' + o);
    });
  });
  if (added.length) log.push(`人物登场，补上背景关系 ${added.length} 条：${added.join('、')}`);
  return log;
}

/** 这一轮按变量判出来已初始化、「登场过」里还没有的人，记进 chat 变量（只加不减，跟名册界面同一个存法）。
 *  名册界面画的时候也会记；这里再记一遍，状态栏没画出来（折起来、没开）也不漏 */
function xdNoteSeen(stat, ctx) {
  if (!ctx || !ctx.ok) return;
  const have = new Set(ctx.seen);
  const add = Array.from(xdInited(stat, ctx)).filter(k => !have.has(k));
  if (!add.length || typeof TavernHelper.updateVariablesWith !== 'function') return;
  return Promise.resolve().then(() => TavernHelper.updateVariablesWith(v => {
    const cur = Array.isArray(v[XD_SEEN_KEY]) ? v[XD_SEEN_KEY].slice() : [];
    add.forEach(k => { if (cur.indexOf(k) < 0) cur.push(k); });
    v[XD_SEEN_KEY] = cur;
    return v;
  }, { type: 'chat' })).catch(e => console.error('[数据层] 登场名单写入失败', e));
}

/** 关系清理，就地改 stat，返回删了什么（一条一句）。
 *  认不出主角名（空着 / 未定）时，「端点不在名册」这条整轮不删——跟以前 db-guard.js 一个原则：
 *  认不出就不动，宁可留着，不能把「客体是主角」的边当成名册里没这人一口气删光。
 *  ctx = xdChatCtx()：已删除的人的边删掉；背景边有一端没初始化的删掉（见上面「懒加载」） */
function xdCleanRelations(stat, ctx) {
  const log = [];
  if (!xdObj(stat) || stat.关系 === undefined) return log;
  if (!xdObj(stat.关系)) { stat.关系 = {}; log.push('关系不是对象，清空'); return log; }
  const rel = stat.关系;
  const roster = xdObj(stat.角色名册) ? stat.角色名册 : {};
  const inRoster = n => xdHas(roster, n) && xdObj(roster[n]);
  const me = xdPlayerName(stat);
  for (const s of Object.keys(rel)) {
    if (me && s === me) { delete rel[s]; log.push(`主体是主角「${s}」，整组删掉`); continue; }
    if (me && !inRoster(s)) { delete rel[s]; log.push(`主体「${s}」不在名册里，整组删掉`); continue; }
    const row = rel[s];
    if (!xdObj(row)) { delete rel[s]; log.push(`「${s}」那一组不是对象，删掉`); continue; }
    for (const o of Object.keys(row)) {
      const why = xdEdgeWhy(s, o, row[o], inRoster, me);
      if (why) { delete row[o]; log.push(`${s} → ${o}：${why}，删掉`); }
    }
    if (!Object.keys(row).length) delete rel[s];
  }
  if (!ctx) return log;
  const del = new Set(ctx.del);
  const inited = ctx.ok && me ? xdInited(stat, ctx) : null;
  const gone = [], later = [];
  for (const s of Object.keys(rel)) {
    const row = rel[s];
    for (const o of Object.keys(row)) {
      if (del.has(s) || del.has(o)) { delete row[o]; gone.push(s + ' → ' + o); continue; }
      if (inited && !xdTxt(row[o] && row[o].最近一次交互) && xdBgOf(s, o, me, ctx.role)
          && (!inited.has(s) || (o !== me && !inited.has(o)))) { delete row[o]; later.push(s + ' → ' + o); }
    }
    if (!Object.keys(row).length) delete rel[s];
  }
  if (gone.length) log.push(`已删除的人的关系 ${gone.length} 条，删掉（不发送）：${gone.join('、')}`);
  if (later.length) log.push(`有一端还没登场的背景关系 ${later.length} 条，先不放进变量`);
  return log;
}

/** 不在场的人身上是默认值的格子（src/data_field.py 的 strip_absent 同一个口径）：
 *  是否在场 false / 身份 空 / 生死 生。
 *  缺了就是默认值：MVU 解析时 schema 的 catch 会补回来，这里落盘前再删，所以 MVU 那趟请求里
 *  不在场的人只剩 当前境界 / 年龄 和不是默认值的格子（2026-09-25 名册涨到 109 人，这几格占了名册一大半 token） */
function xdIsDefault(p, f) {
  const v = p[f];
  if (f === '是否在场') return v === false;
  if (f === '身份') return v === '';
  if (f === '生死') return v === '生';
  return false;
}
const XD_DEFAULTS = ['是否在场', '身份', '生死'];

/** 不在场的人（含死人）删掉五个场景字段和是默认值的那几格，返回动了谁 */
function xdStripAbsent(stat) {
  const log = [];
  const r = xdObj(stat) && xdObj(stat.角色名册) ? stat.角色名册 : null;
  if (!r) return log;
  for (const k of Object.keys(r)) {
    const p = r[k];
    if (!xdObj(p)) continue;
    delete p.完成状态; // 清理旧存档中已退役的统计字段
    if (p.是否在场 === true && xdTxt(p.生死) !== '死') continue;
    const had = XD_SCENE.filter(f => xdHas(p, f));
    had.forEach(f => { delete p[f]; });
    // 默认值那几格删了不记日志：预登记的一百多人每一轮都要过一遍，记下来是满屏废话
    XD_DEFAULTS.forEach(f => { if (xdHas(p, f) && xdIsDefault(p, f)) delete p[f]; });
    // 年龄空着（表里没有的人，zod 的 catch 补成 ""）也不写
    if (p.年龄 === '') delete p.年龄;
    if (had.length) log.push(k);
  }
  return log.length ? [`不在场，删掉场景字段：${log.join('、')}`] : [];
}

/** 数量 ≤ 0 的物品删掉（数量不是数的也一样，zod 那头本该已经丢了） */
function xdDropSpent(stat) {
  const bag = xdObj(stat) && xdObj(stat.玩家) && xdObj(stat.玩家.物品) ? stat.玩家.物品 : null;
  if (!bag) return [];
  const gone = Object.keys(bag).filter(k => !xdObj(bag[k]) || !(Number(bag[k].数量) > 0));
  gone.forEach(k => { delete bag[k]; });
  return gone.length ? [`用完了，删掉物品：${gone.join('、')}`] : [];
}

/** 名叫「-」或纯数字的物品 / 功法删掉：那是 add …/物品/- 、…/功法/0 这种数组写法建出来的，不是名字 */
function xdDropJunkKeys(stat) {
  const me = xdObj(stat) && xdObj(stat.玩家) ? stat.玩家 : null;
  if (!me) return [];
  const log = [];
  ['功法', '物品'].forEach(key => {
    const t = xdObj(me[key]) ? me[key] : null;
    if (!t) return;
    const bad = Object.keys(t).filter(k => k.trim() === '-' || /^\d+$/.test(k.trim()) || !k.trim());
    bad.forEach(k => { delete t[k]; });
    if (bad.length) log.push(`${key}的键「${bad.join('、')}」不是名字，删掉`);
  });
  return log;
}

/* ---------- 这一轮写坏了的，补回更新前的原样 ----------
 * zod 那头是「坏一条只丢那一条」，可已有的那一条被写坏也会整条消失——那不是 AI 想删它。
 * mag_variable_update_ended 里拿 MVU 给的更新前变量补：
 *   玩家    姓名 / 性别 / 年龄 / 出身 / 定位是开局定死的（禁止更新），跟更新前不一样就改回去；
 *           整个「玩家」被 replace / remove 时，写进去的值里没有的 当前境界 / 身体状态 / 当前服装 也补回。
 *   功法    规则写的是「功法不删」，这一轮消失的已有功法一律补回，AI 用 remove 删的也补。
 *   物品    能正常用掉、送出，只补「校验丢」的。算主动删、不补的：remove 指着它或整张物品表；
 *           move 把它挪走；replace / add 把整张物品表换成一张**有效**的新表（至少一件过得了校验）。
 *           整个「玩家」被覆盖不算删物品；写进去的表是坏的（路径少一层之类）也不算。
 *           数量归零的不在这里管——那一条这时还在，接下来 xdDropSpent 删它。
 *   关系    规则写的是「不要 remove 关系」，已有的边这一轮消失了（remove、整组覆盖、校验丢），补回原样。
 *           边里某一格写坏了不在这里管，schema 各格自己 catch，xdFillSays 沿用上一楼的。补回排在 xdClean 前面，
 *           主角当主体、端点不在名册、自己对自己的边补回来也照删。
 * 要知道这一轮有哪些命令：MVU 发 mag_command_parsed 时（mvu_zod 执行、清空命令列表之前）抄一份，
 * 按变量对象记在 WeakMap 里，mag_variable_update_ended 拿同一个对象取出来。拿不到就当没有主动删。 */

const XD_LOCK = ['姓名', '性别', '年龄', '出身', '定位'];
const XD_SOFT = ['当前境界', '身体状态', '当前服装'];

function xdParse(v) {
  if (typeof v !== 'string') return v;
  try { return JSON.parse(v); } catch (e) { return v; }
}

/** 命令 -> {type: set|insert|delete|add, path: ['玩家', '物品', '某物'], value}。
 *  insert 的完整路径 = 父路径 + 键（两参的 insert 是合并，不删东西，不记）；move = 从 from 删 + 往 to 写 */
function xdCmdPaths(cmds) {
  const strip = s => String(s == null ? '' : s).replace(/^[\\"'` ]*(.*?)[\\"'` ]*$/, '$1').replace(/^(?:stat_data|status_current_variables)\./, '');
  const path = s => (strip(s) ? _.toPath(strip(s)) : []);
  const out = [];
  (Array.isArray(cmds) ? cmds : []).forEach(c => {
    if (!c || !Array.isArray(c.args) || !c.args.length) return;
    const t = c.type === 'remove' || c.type === 'unset' ? 'delete' : c.type;
    if (t === 'insert' || t === 'assign') {
      if (c.args.length < 3) return;
      const k = xdParse(c.args[1]);
      out.push({ type: 'insert', path: path(c.args[0]).concat([typeof k === 'string' ? strip(k) : String(k)]), value: xdParse(c.args[c.args.length - 1]) });
    } else if (t === 'move') {
      out.push({ type: 'delete', path: path(c.args[0]) });
      if (c.args.length > 1) out.push({ type: 'set', path: path(c.args[1]), value: undefined });
    } else if (t === 'set' || t === 'add') {
      out.push({ type: t, path: path(c.args[0]), value: xdParse(c.args[c.args.length - 1]) });
    } else if (t === 'delete') {
      out.push({ type: 'delete', path: path(c.args[0]) });
    }
  });
  return out;
}

function xdSame(a, b) { return a.length === b.length && a.every((x, i) => x === b[i]); }
function xdPre(a, b) { return a.length <= b.length && a.every((x, i) => x === b[i]); }

/** 数量过得了校验：数字，或者写成数字的非空字符串（跟 schema 一个认法） */
function xdNumOk(v) {
  const n = typeof v === 'number' ? v : (typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN);
  return Number.isFinite(n);
}
function xdItemOk(v) { return xdObj(v) && xdNumOk(v.数量); }

/** 这一轮是不是主动删了这件物品（见上面那段） */
function xdItemDropped(paths, name) {
  const item = ['玩家', '物品', name], table = ['玩家', '物品'];
  return paths.some(c => {
    if (c.type === 'delete') return c.path.length >= 2 && xdPre(c.path, item);
    if (c.type === 'set' || c.type === 'insert') {
      return xdSame(c.path, table) && xdObj(c.value) && Object.keys(c.value).some(k => xdItemOk(c.value[k]));
    }
    return false;
  });
}

/** 就地补回，返回日志。before 是这一轮更新之前的 stat_data，cmds 是这一轮的命令（拿不到就当没有主动删） */
function xdRestore(stat, before, cmds) {
  const log = [];
  if (!xdObj(stat) || !xdObj(before)) return log;
  const paths = xdCmdPaths(cmds);
  const wasMe = xdObj(before.玩家) ? before.玩家 : null;
  if (wasMe) {
    if (!xdObj(stat.玩家)) stat.玩家 = {};
    const me = stat.玩家;
    // 禁止更新的五格：不一样就改回去
    const fixed = XD_LOCK.filter(f => wasMe[f] !== undefined && me[f] !== wasMe[f]);
    fixed.forEach(f => { me[f] = wasMe[f]; });
    // 整个「玩家」被覆盖：写进去的值里没有的那几格补回（写了的是 AI 的意思，照写的算）
    paths.filter(c => c.path.length < 2 && xdPre(c.path, ['玩家'])).forEach(c => {
      const wrote = c.type === 'delete' ? {} : (c.path.length === 1 ? c.value : (xdObj(c.value) ? c.value.玩家 : undefined));
      if (c.type !== 'delete' && !xdObj(wrote)) return;       // 写的不是对象：整条命令本来就作废了
      XD_SOFT.forEach(f => {
        if (!xdHas(wrote, f) && wasMe[f] !== undefined && me[f] !== wasMe[f]) { me[f] = wasMe[f]; fixed.push(f); }
      });
    });
    if (fixed.length) log.push(`玩家的 ${Array.from(new Set(fixed)).join(' / ')} 被改了，改回去`);
    [['功法', false], ['物品', true]].forEach(([key, canDrop]) => {
      const was = xdObj(wasMe[key]) ? wasMe[key] : null;
      if (!was) return;
      if (!xdObj(me[key])) me[key] = {};
      const now = me[key];
      const back = Object.keys(was).filter(k => xdObj(was[k]) && !xdHas(now, k) && !(canDrop && xdItemDropped(paths, k)));
      back.forEach(k => { now[k] = JSON.parse(JSON.stringify(was[k])); });
      if (back.length) log.push(`${key}「${back.join('、')}」这一轮写坏了，补回原样`);
    });
  }
  const was = xdObj(before.关系) ? before.关系 : null;
  if (was) {
    if (!xdObj(stat.关系)) stat.关系 = {};
    const back = [];
    Object.keys(was).forEach(s => {
      if (!xdObj(was[s])) return;
      Object.keys(was[s]).forEach(o => {
        if (!xdObj(was[s][o])) return;
        const row = stat.关系[s];
        if (xdObj(row) && xdHas(row, o) && xdObj(row[o])) return;
        if (!xdObj(stat.关系[s])) stat.关系[s] = {};
        stat.关系[s][o] = JSON.parse(JSON.stringify(was[s][o]));
        back.push(s + ' → ' + o);
      });
    });
    if (back.length) log.push(`关系「${back.join('、')}」这一轮写坏了，补回原样`);
  }
  return log;
}

/* ---------- 称呼 / 自称：按场景的说法 ----------
 * 边上的 称呼 / 自称 都是 [{场景, 称呼}] / [{场景, 自称}]，第一项是平时的说法，空数组 = 还不知道。
 * xdSays 是跟 schema（data_field.py 的 场景说法）同一个认法的归一：没过 zod 的老数据（字符串、缺格）也按它读。
 *
 * xdFillSays（mag_variable_update_ended，清理之后）：
 *   关系名、称呼、自称、最近一次交互：已有的边这一格是空的、上一楼这条边这一格不空 → 沿用上一楼的。关系变了整条 replace 时漏写、
 *            写成空的、写坏了被 schema 落空，都不该把原来的冲掉。
 *   类别：不在词表里（写错了被 schema 落空、没写）→ 已有的边沿用上一楼的，新边（或上一楼也没有）兜底「交情」。
 *   自称还有原著表（称呼没有）。用户定的：原著里查得到的写死，查不到的空着，以后由 AI 随剧情改：
 *     新建的边（更新前的变量里没有这一条）  表里有就用表里的整组，覆盖 AI 写的；表里没有，AI 写什么留什么。
 *     已有的边                              不空就不动（AI 改过的，或者早先按表填的）；空的（上一楼也空）表里有就补上。
 * 「表里的值」= 这一对里时刻已经到了（at ≤ 当前时刻）的最后一段；一段都没到取最早那段。
 * 当前时刻 = 这一轮写完之后的纪元时刻；这一轮写坏了读不出来，用上一楼的；那也读不出来，按「一段都没到」办。
 * 拿不到更新前的变量（mag_before_message_update 那一趟）就分不出新旧，一律按已有的边办——只补空的，不会覆盖 AI。 */

const XD_SAYS = ['称呼', '自称'];
function xdKind(k) { return typeof k === 'string' && (XD_VOCAB.relKinds || []).indexOf(k) > -1; }

/** 任意值 -> [{场景, key}]。跟 schema、界面同一份（data_field.py 的 SAYS_JS，build_card.py 核对一字不差） */
function xdSays(v, key) {
  const other = key === '称呼' ? '自称' : '称呼';
  const isObj = x => !!x && typeof x === 'object' && !Array.isArray(x);
  const text = x => (typeof x === 'string' ? x.trim() : (typeof x === 'number' ? String(x) : ''));
  if (typeof v === 'string' || typeof v === 'number' || isObj(v)) v = [v];
  if (!Array.isArray(v)) return [];
  const got = [];
  const put = (scene, say) => {
    scene = text(scene); say = text(say);
    if (!scene || !say) return;
    const hit = got.find(x => x.场景 === scene);
    if (hit) hit[key] = say; else got.push({ 场景: scene, [key]: say });
  };
  v.forEach(x => {
    if (typeof x === 'string' || typeof x === 'number') {
      if (text(x)) put(got.some(y => y.场景 === '平时') ? '有时' : '平时', x);
      return;
    }
    if (!isObj(x)) return;
    if (x.场景 !== undefined) { put(x.场景, x[key] !== undefined ? x[key] : x[other]); return; }
    Object.keys(x).forEach(k => { if (k !== key && k !== other) put(k, x[k]); });
  });
  const i = got.findIndex(x => x.场景 === '平时');
  if (i > 0) got.unshift(got.splice(i, 1)[0]);
  return got.slice(0, 4);
}

/** [{场景, key}] -> 「我」（温言时「远哥哥」；发狠时「老子」）。没有「平时」那项就全放括号里 */
function xdSaysText(list, key) {
  if (!list.length) return '';
  const head = list[0].场景 === '平时' ? list[0] : null;
  const rest = (head ? list.slice(1) : list).map(x => x.场景 + '「' + x[key] + '」');
  return (head ? '「' + head[key] + '」' : '') + (rest.length ? '（' + rest.join('；') + '）' : '');
}

function xdPlain(v) { return Array.isArray(v) && v.length === 2 && typeof v[1] === 'string' ? v[0] : v; }

/** 系统.纪元时刻 -> 分钟（time-core.js 的 xxToMin）；读不出来返回 null */
function xdNowMin(stat) {
  const sys = xdObj(stat) && xdObj(stat.系统) ? stat.系统 : null;
  if (!sys || typeof xxToMin !== 'function') return null;
  return xxToMin(String(xdPlain(sys.纪元时刻) || ''));
}

/** 原著里 s 当着 o 此刻的那组自称 [{场景, 自称}]；表里没有这一对返回空数组 */
function xdCanonSelf(tab, s, o, now) {
  const list = xdObj(tab) && xdHas(tab, s) && xdObj(tab[s]) && xdHas(tab[s], o) && Array.isArray(tab[s][o]) ? tab[s][o] : [];
  if (!list.length) return [];
  let got = null;
  if (typeof now === 'number' && isFinite(now)) {
    list.forEach(x => { if (Array.isArray(x) && typeof x[0] === 'number' && x[0] <= now) got = x; });
  }
  got = got || list[0];
  return Array.isArray(got) ? xdSays(got[1], '自称') : [];
}

/** 就地填，返回日志。before 是更新前的 stat_data，null = 拿不到（一律按已有的边办）。
 *  顺手把两格归一成数组（没过 zod 的老数据是字符串或者缺格） */
function xdFillSays(stat, before, tab) {
  const log = [];
  const rel = xdObj(stat) && xdObj(stat.关系) ? stat.关系 : null;
  if (!rel) return log;
  const was = xdObj(before) ? (xdObj(before.关系) ? before.关系 : {}) : null;
  let now = xdNowMin(stat);
  if (now === null) now = xdNowMin(before);
  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
  Object.keys(rel).forEach(s => {
    if (!xdObj(rel[s])) return;
    Object.keys(rel[s]).forEach(o => {
      const e = rel[s][o];
      if (!xdObj(e)) return;
      const old = was !== null && xdHas(was, s) && xdObj(was[s]) && xdHas(was[s], o) && xdObj(was[s][o]) ? was[s][o] : null;
      const fresh = was !== null && !old;
      const name = xdTxt(e.关系), oldName = old ? xdTxt(old.关系) : '';
      if (!name && oldName && !fresh) log.push(`${s} → ${o} 的关系名这一轮被写空了，沿用上一楼的「${oldName}」`);
      if (e.关系 !== (name || (fresh ? '' : oldName))) e.关系 = name || (fresh ? '' : oldName);
      if (!xdKind(e.类别)) {
        // 沿用上一楼的；没有的话，老存档的边「关系」写的就是类别词，拿它；都不是兜底「交情」
        const k = old && xdKind(old.类别) ? old.类别 : (xdKind(xdTxt(e.关系)) ? xdTxt(e.关系) : '交情');
        log.push(`${s} → ${o} 的类别${e.类别 === undefined ? '没写' : '「' + e.类别 + '」不对'}，${old && xdKind(old.类别) ? '沿用上一楼的' : '当成'}「${k}」`);
        e.类别 = k;
      }
      XD_SAYS.forEach(key => {
        let cur = xdSays(e[key], key);
        if (!fresh && !cur.length) {
          const kept = old ? xdSays(old[key], key) : [];
          if (kept.length) {
            cur = kept;
            log.push(`${s} → ${o} 的${key}这一轮被写空了，沿用上一楼的${xdSaysText(kept, key)}`);
          }
        }
        if (key === '自称' && (fresh || !cur.length)) {
          const configured = xdBgOf(s,o,xdPlayerName(stat),xdChatCtx().role);
          const want = Object.hasOwn(configured||{},'自称') ? xdSays(configured.自称,'自称') : xdCanonSelf(tab, s, o, now);
          if (want.length && !same(cur, want)) {
            log.push(`${s} → ${o} 的自称按原著${cur.length ? '从' + xdSaysText(cur, key) + '改成' : '补上'}${xdSaysText(want, key)}`);
            cur = want;
          }
        }
        if (!same(e[key], cur)) e[key] = cur;
      });
      // 最近一次交互：整条 replace 漏写了、写成空的，沿用上一楼的
      let last = typeof e.最近一次交互 === 'string' ? e.最近一次交互 : '';
      const oldLast = old && typeof old.最近一次交互 === 'string' ? old.最近一次交互 : '';
      if (!fresh && !last.trim() && oldLast.trim()) {
        last = oldLast;
        log.push(`${s} → ${o} 的最近一次交互这一轮被写空了，沿用上一楼的`);
      }
      // 五格按固定顺序、只留这五格（没过 zod 的老数据可能还带着以前的「亲疏」）。
      // 称呼 / 自称是空数组、最近一次交互是空串的不写：缺了就是空的（schema 解析时 catch 补回来，读的地方都当空），
      // 开局两百多条背景关系大多是这样，省 MVU 请求的 token（2026-09-25，名册涨到 109 人）
      const tidy = { 关系: e.关系, 类别: e.类别 };
      if (e.称呼.length) tidy.称呼 = e.称呼;
      if (e.自称.length) tidy.自称 = e.自称;
      if (last) tidy.最近一次交互 = last;
      if (!same(tidy, e)) rel[s][o] = tidy;
    });
  });
  return log;
}

/** 三样一起，返回全部日志 */
function xdClean(stat, ctx) {
  if (!xdObj(stat)) return [];
  return xdCleanRelations(stat, ctx || xdChatCtx()).concat(xdStripAbsent(stat), xdDropSpent(stat), xdDropJunkKeys(stat));
}

/** 这一轮该参照的那一楼的 stat_data（原对象，别改它）。
 *  swipe / regenerate 时最后那条 AI 楼是要被换掉的，跳过——同 life.js 的 lfRosterNow */
function xdStatNow(chat, type) {
  if (!Array.isArray(chat) || !chat.length) return null;
  let i = chat.length - 1;
  if ((type === 'swipe' || type === 'regenerate') && i > 0 && chat[i] && !chat[i].is_user) i--;
  for (; i >= 0; i--) {
    const m = chat[i];
    const v = m && m.variables && m.variables[m.swipe_id || 0];
    if (v && xdObj(v.stat_data)) return v.stat_data;
  }
  return null;
}

/* ---------- 注入块的拼装 ---------- */

/** 「南宫婉 → 萧曦月：徒弟，称呼「曦月」（动怒时「孽徒」），自称「为师」，最近：……」。
 *  冒号后头一个词 = 在主体眼里客体是他的什么人；关系名空着就写类别。称呼、自称平时那项直接写，
 *  别的场景按「场景「说法」」放括号里；空数组就不写那一段 */
function xdRelLine(s, o, e) {
  const seg = [];
  const name = xdTxt(e.关系) || (xdKind(e.类别) ? e.类别 : '');
  if (name) seg.push(name);
  XD_SAYS.forEach(key => { const t = xdSaysText(xdSays(e[key], key), key); if (t) seg.push(key + t); });
  if (xdTxt(e.最近一次交互)) seg.push(((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdRelLine.81ff5ae0916c",[xdTxt(e.最近一次交互)]) ?? ('最近：' + xdTxt(e.最近一次交互))));
  return s + ' → ' + o + '：' + seg.join('，');
}

/** 要注入的那几行：只发跟眼前有关的边——主体或客体在场（是否在场 为 true、没死），或者客体是主角（别人怎么看主角全发）。
 *  开局就预置了一百多条背景关系，全发一轮要好几千 token；不在场的两个人之间的关系，这一轮用不上 */
function xdRelLines(stat) {
  const rel = xdObj(stat) && xdObj(stat.关系) ? stat.关系 : {};
  const roster = xdObj(stat) && xdObj(stat.角色名册) ? stat.角色名册 : {};
  const me = xdPlayerName(stat);
  const here = n => xdHas(roster, n) && xdObj(roster[n]) && roster[n].是否在场 === true && xdTxt(roster[n].生死) !== '死';
  const out = [];
  Object.keys(rel).forEach(s => {
    if (!xdObj(rel[s])) return;
    Object.keys(rel[s]).forEach(o => {
      if (!xdObj(rel[s][o])) return;
      if (here(s) || here(o) || (me && o === me)) out.push(xdRelLine(s, o, rel[s][o]));
    });
  });
  return out;
}

function xdRelBlock(lines) { const pointOutput=(()=>{
  return [((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdRelBlock.7bcde662519b",[]) ?? ('<人物关系>')),
    ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdRelBlock.709243d226c7",[]) ?? ('这是本局到此为止已经确立的人际关系里跟眼前有关的：在场的人的，和别人对主角的。一行一条，方向是「主体 → 客体」。')),
    ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdRelBlock.c417f9869512",[]) ?? ('冒号后头一个词是在主体眼里客体是他的什么人：「南宫婉 → 萧曦月：徒弟」是说萧曦月是南宫婉的徒弟。')),
    ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdRelBlock.fbb1e01c5f05",[]) ?? ('A 对 B 和 B 对 A 各是一行；只列了一头的就是单方面的。')),
    ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdRelBlock.a135e93abd26",[]) ?? ('「称呼」是主体当着客体的面怎么叫对方，「自称」是他当着客体怎么称呼自己；括号里是某个场景下改用的说法，不在那个场景就用括号前平时的。写对话时照着用，别叫错辈分。')),
    ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdRelBlock.01cb60999a75",[]) ?? ('主角只在客体那一侧：他怎么看别人由玩家自己演，这里不记，你也别替他定。')),
    ''].concat(lines).concat([((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdRelBlock.da2016647b7e",[]) ?? ('</人物关系>'))]).join('\n');
})(); if(!pointOutput)return pointOutput; return ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("point.relations",[lines.join('\n')]) ?? pointOutput); }

/** 主角近况：空的、还是默认值的不写；一行都没有就返回空串 */
function xdPlayerBlock(stat) {
  const me = xdObj(stat) && xdObj(stat.玩家) ? stat.玩家 : null;
  if (!me) return '';
  const lines = [];
  const body = xdTxt(me.身体状态), cloth = xdTxt(me.当前服装);
  if (body && body !== '正常') lines.push(((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdPlayerBlock.a06d0c562896",[body]) ?? ('身体状态：' + body)));
  if (cloth && cloth !== '未知') lines.push(((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdPlayerBlock.24d8ff84002e",[cloth]) ?? ('当前服装：' + cloth)));
  const arts = xdObj(me.功法) ? me.功法 : {};
  const a = Object.keys(arts).filter(k => xdObj(arts[k])).map(k => {
    const x = arts[k], tag = [xdTxt(x.类型), xdTxt(x.熟练度)].filter(Boolean).join('·');
    return k + (tag ? '（' + tag + '）' : '') + (xdTxt(x.说明) ? '：' + xdTxt(x.说明) : '');
  });
  if (a.length) lines.push(((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdPlayerBlock.a697a47e005b",[a.join('；')]) ?? ('功法：' + a.join('；'))));
  const bag = xdObj(me.物品) ? me.物品 : {};
  const b = Object.keys(bag).filter(k => xdObj(bag[k]) && Number(bag[k].数量) > 0).map(k => {
    const x = bag[k];
    return k + ' ×' + Number(x.数量) + (xdTxt(x.说明) ? '（' + xdTxt(x.说明) + '）' : '');
  });
  if (b.length) lines.push(((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdPlayerBlock.2c4767ccd41f",[b.join('；')]) ?? ('物品：' + b.join('；'))));
  if (!lines.length) return '';
  const name = xdPlayerName(stat);
  return ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("point.status",[name,lines.join('\n')]) ?? ([((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdPlayerBlock.2e5c2d3369db",[]) ?? ('<主角近况>')), ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdPlayerBlock.9160a1f53abd",[name ? '（' + name + '）' : '']) ?? (`主角${name ? '（' + name + '）' : ''}此刻的样子和身上的东西，写正文时以这里为准：`))]
    .concat(lines, [((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdPlayerBlock.8f4075023042",[]) ?? ('</主角近况>'))]).join('\n')));
}

/** 在场的新人物（不在原著名单里、写了 简介 或 外貌 的）；一个都没有就返回空串 */
function xdNewcomerBlock(stat, canon) {
  const r = xdObj(stat) && xdObj(stat.角色名册) ? stat.角色名册 : {};
  const known = new Set(canon || []);
  const lines = [];
  Object.keys(r).forEach(k => {
    const p = r[k];
    if (!xdObj(p) || p.是否在场 !== true || xdTxt(p.生死) === '死' || known.has(k)) return;
    const seg = [];
    if (xdTxt(p.简介)) seg.push(xdTxt(p.简介));
    if (xdTxt(p.外貌)) seg.push(((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdNewcomerBlock.5c2747bf8179",[xdTxt(p.外貌)]) ?? ('外貌：' + xdTxt(p.外貌))));
    if (seg.length) lines.push(k + '：' + seg.join('；'));
  });
  if (!lines.length) return '';
  return ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("point.newcomer",[lines.join('\n')]) ?? ([((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdNewcomerBlock.b2fb59524238",[]) ?? ('<新登场人物>')), ((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdNewcomerBlock.9ad6084c368b",[]) ?? ('原著里没有这几个人，世界书里查不到，照这里写：'))].concat(lines, [((globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render("mvu-data.js:xdNewcomerBlock.60060dd078cd",[]) ?? ('</新登场人物>'))]).join('\n')));
}

/** 这一轮要注入什么：{rel, me}，各是一段文本或空串。stat 不会被改（在副本上清理）。
 *  statVisible = 正文模型本来就看得见 stat_data（「随AI输出」模式），那就一块都不发 */
function xdBlocks(stat, statVisible, canon) {
  if (!xdObj(stat) || statVisible) return { rel: '', me: '' };
  const s = JSON.parse(JSON.stringify(stat));
  xdClean(s);
  const lines = xdRelLines(s);
  const me = [xdPlayerBlock(s), xdNewcomerBlock(s, canon)].filter(Boolean).join('\n\n');
  return { rel: lines.length ? xdRelBlock(lines) : '', me: me };
}

/* ---------- 挂到酒馆上 ---------- */

const xdCmds = new WeakMap();      // 变量对象 -> 这一轮的命令（抄的副本）

/** 命令要碰的格子被省掉了（缺了 = 默认值，见 xdStripAbsent / xdFillSays），先补上默认值再让 mvu_zod 执行：
 *  delta 打在缺格上会失败（mvu_zod 要求原值是数）、往缺掉的数组按下标 add 会建出一个对象
 *  （「自称/0」）。只补命令路径经过的那一格，而且只补已经在名册里的人、已经有的边；别的一概不动。
 *  补了什么返回日志（名字 → 格子） */
function xdFillTouched(stat, cmds) {
  const log = [];
  if (!xdObj(stat)) return log;
  const roster = xdObj(stat.角色名册) ? stat.角色名册 : null, rel = xdObj(stat.关系) ? stat.关系 : null;
  const dflt = { 是否在场: () => false, 身份: () => '', 生死: () => '生' };
  const edgeDflt = { 称呼: () => [], 自称: () => [], 最近一次交互: () => '' };
  xdCmdPaths(cmds).forEach(c => {
    const p = c.path;
    if (p.length >= 3 && p[0] === '角色名册' && roster && xdHas(roster, p[1]) && xdObj(roster[p[1]])
        && xdHas(dflt, p[2]) && !xdHas(roster[p[1]], p[2]) && (p.length > 3 || c.type === 'add')) {
      roster[p[1]][p[2]] = dflt[p[2]]();
      log.push(p[1] + '.' + p[2]);
    } else if (p.length >= 4 && p[0] === '关系' && rel && xdObj(rel[p[1]]) && xdHas(rel[p[1]], p[2]) && xdObj(rel[p[1]][p[2]])
        && xdHas(edgeDflt, p[3]) && !xdHas(rel[p[1]][p[2]], p[3]) && (p.length > 4 || c.type === 'add')) {
      rel[p[1]][p[2]][p[3]] = edgeDflt[p[3]]();
      log.push(p[1] + '→' + p[2] + '.' + p[3]);
    }
  });
  return log;
}

/** 抄一份这一轮的命令（按 MVU 给的那袋变量记），再把命令要碰的缺格补上。出错就抛（事务里用） */
function xdStepParsed(vars, cmds, key) {
  if (key && typeof key === 'object') xdCmds.set(key, JSON.parse(JSON.stringify(cmds || [])));
  const got = xdFillTouched(vars && vars.stat_data, cmds);
  if (got.length) console.info('[数据层] 命令要碰的格子先补上默认值：' + got.join('、'));
}

function xdOnParsed(vars, cmds) {
  try { if (vars && typeof vars === 'object') xdCmds.set(vars, JSON.parse(JSON.stringify(cmds || []))); } catch (e) { }
  try { xdStepParsed(vars, cmds, null); } catch (e) { console.error('[数据层] 补缺格出错', e); }
}

/** mag_variable_update_ended：先补回校验丢掉的，再清理，最后补称呼 / 自称。before 是 MVU 给的更新前变量 */
function xdStepUpdated(vars, before, key, defer) {
  {
    const stat = vars && vars.stat_data;
    const was = before && xdObj(before.stat_data) ? before.stat_data : null;
    let log = [];
    const ctx = xdChatCtx();
    const k = key && typeof key === 'object' ? key : vars;
    if (was) log = xdRestore(stat, was, k ? xdCmds.get(k) : null);
    log = log.concat(xdClean(stat, ctx));
    // 懒加载：这一轮登场的人的背景关系补进来（排在清理后面、补称呼自称前面：补进来的是新边，xdFillSays 照新边的规矩收尾）
    let now = xdNowMin(stat);
    if (now === null) now = xdNowMin(was);
    log = log.concat(xdBgFill(stat, ctx, now));
    log = log.concat(xdFillSays(stat, was, XD_SELF));
    // 记「登场过」是写 chat 变量（stat_data 以外）：事务提交之后才写（src/mvu-txn.js），这一轮失败了就不写
    const seenStat = JSON.parse(JSON.stringify(stat || {}));
    (defer || (fn => fn()))(() => xdNoteSeen(seenStat, ctx));
    if (log.length) console.info('[数据层] ' + log.join('；'));
  }
}

function xdOnUpdated(vars, before) {
  try { xdStepUpdated(vars, before, vars); } catch (e) { console.error('[数据层] 清理出错', e); }
}

function xdOnBeforeMessage(payload) {
  xdOnUpdated(payload && payload.variables);
}

/** 「随AI输出」时正文模型看得见 stat_data；读不到设置就当看不见（多发一小段，不会少发） */
function xdStatVisible() {
  try { return _.get(SillyTavern, 'extensionSettings.mvu_settings.更新方式') === '随AI输出'; } catch (e) { return false; }
}

/** 注入深度：贴着最近一楼。别取「楼数-1」——酒馆按预算裁历史，深度越界会被悄悄丢掉（见 README） */
function xdDepth() {
  try { return (SillyTavern.getContext().chat || []).length > 1 ? 1 : 0; } catch (e) { return 1; }
}

function xdInject(type) {
  try {
    if (typeof xzTxnDual === 'function' && xzTxnDual()) { TavernHelper.uninjectPrompts([XD_REL_ID, XD_ME_ID]); return; }
    if (typeof duringUpdate === 'function' && duringUpdate()) {
      TavernHelper.uninjectPrompts([XD_REL_ID, XD_ME_ID]);
      return;
    }
    let chat = null;
    try { chat = SillyTavern.getContext().chat; } catch (e) { chat = null; }
    const got = xdBlocks(xdStatNow(chat, type), xdStatVisible(), XD_CANON);
    const put = [], drop = [];
    [[XD_REL_ID, got.rel], [XD_ME_ID, got.me]].forEach(([id, text]) => {
      if (!text) { drop.push(id); return; }
      put.push({ id: id, position: 'in_chat', depth: xdDepth(), role: 'system', content: text, should_scan: false });
    });
    if (drop.length) TavernHelper.uninjectPrompts(drop);
    if (put.length) {
      TavernHelper.injectPrompts(put, { once: true });
      console.info(`[数据层] 注入 ${put.map(p => p.id === XD_REL_ID ? '人物关系' : '主角近况').join('、')}`);
    }
  } catch (e) {
    console.warn('[数据层] 注入出错', e);
  }
}

/** 楼层推进时清删人快照（src/del-snap.js）：正在写的这一楼（提示词模板扩展从上一楼抄过来的那袋）里过期的、已经恢复了的清掉；
 *  「已删除」里超过 10 楼的，删除那一楼自己存的那张也清掉。只动 删人快照 这一个顶层键。
 *  事务提交之后才做（tx.after）；chat 变量读不出来就只按楼数清 */
function xdSnapPrune() {
  try {
    if (typeof dsPrune !== 'function') return;
    const chat = SillyTavern.getContext().chat || [];
    const floor = chat.length - 1;
    if (floor < 0) return;
    let items = null;
    try { const v = TavernHelper.getVariables({ type: 'chat' }); items = Array.isArray(v && v[XD_DEL_KEY]) ? v[XD_DEL_KEY] : []; } catch (e) { items = null; }
    const floors = new Set([floor]);
    (items || []).forEach(x => { if (xdObj(x) && Number.isInteger(x.楼) && x.楼 < floor && floor - x.楼 > DS_KEEP) floors.add(x.楼); });
    floors.forEach(mid => {
      const bag = dsBag(chat, mid);
      if (!bag || !xdObj(bag[DS_KEY])) return;
      const gone = dsPrune(JSON.parse(JSON.stringify(bag)), floor, items);
      if (!gone.length) return;
      Promise.resolve(TavernHelper.updateVariablesWith(w => { dsPrune(w, floor, items); return w; }, { type: 'message', message_id: mid }))
        .catch(e => console.error('[数据层] 删人快照清不掉', e));
      console.info(`[数据层] 第 ${mid} 楼的删人快照清掉：${gone.join('、')}（过了 ${DS_KEEP} 楼或者已经恢复）`);
    });
  } catch (e) { console.warn('[数据层] 删人快照清理出错', e); }
}

// 有事务（src/mvu-txn.js）就登记进去：三步都在工作副本上改，整轮走通才写回；
// 没有（离线测试只切了这一段）就照旧自己挂，出错只记日志
if (typeof xzTxnOn === 'function') {
  xzTxnOn('mag_command_parsed', '数据层补缺格', (v, cmds, text, tx) => xdStepParsed(v, cmds, tx.orig));
  xzTxnOn('mag_variable_update_ended', '数据层整理', (v, before, tx) => xdStepUpdated(v, before, tx.orig, tx.after));
  xzTxnOn('mag_before_message_update', '数据层落盘前清理', (p, tx) => xdStepUpdated(p && p.variables, undefined, null, tx.after));
  xzTxnOn('mag_before_message_update', '删人快照过期清理', (p, tx) => tx.after(xdSnapPrune));
} else {
  eventOn('mag_command_parsed', xdOnParsed);
  eventOn('mag_variable_update_ended', xdOnUpdated);
  eventOn('mag_before_message_update', xdOnBeforeMessage);
}
/** 生成之前把「这一轮该参照的那一楼」的 stat_data.关系 按懒加载 / 删除名单的规矩清一遍，写回那一楼。
 *  为什么要在这儿：清理本来在 MVU 更新完才跑（mag_variable_update_ended），老存档（整本 236 条背景关系铺在变量里）
 *  或者刚点了 ×、名单改了还没过一轮的，第一趟 MVU 请求会把这些边原样带出去；新楼的变量是从这一楼拷过去的，
 *  在生成前清掉，那一趟请求里就没有了。只动 关系 这一格；清不出东西就不写；chat 变量读不出来不清（认不出就不动）。
 *  MVU 自己那趟变量更新请求不走这里（duringUpdate） */
function xdPreClean(type) {
  try {
    if (typeof xzTxnDual === 'function' && xzTxnDual()) return;
    if (typeof duringUpdate === 'function' && duringUpdate()) return;
    const ctx = xdChatCtx();
    if (!ctx.ok) return;
    const chat = SillyTavern.getContext().chat || [];
    let i = chat.length - 1;
    if ((type === 'swipe' || type === 'regenerate') && i > 0 && chat[i] && !chat[i].is_user) i--;
    for (; i >= 0; i--) {
      const m = chat[i];
      const v = m && m.variables && m.variables[m.swipe_id || 0];
      if (v && xdObj(v.stat_data)) break;
    }
    if (i < 0) return;
    const m = chat[i], v = m.variables[m.swipe_id || 0];
    if (!xdObj(v.stat_data.关系)) return;
    const copy = JSON.parse(JSON.stringify(v.stat_data));
    const log = xdCleanRelations(copy, ctx);
    if (!log.length) return;
    const rel = copy.关系;
    Promise.resolve(TavernHelper.updateVariablesWith(w => {
      if (w && xdObj(w.stat_data)) w.stat_data.关系 = rel;
      return w;
    }, { type: 'message', message_id: i })).catch(e => console.error('[数据层] 生成前清理写不回去', e));
    console.info(`[数据层] 生成前清理第 ${i} 楼的关系：${log.join('；')}`);
  } catch (e) {
    console.warn('[数据层] 生成前清理出错', e);
  }
}

eventOn(tavern_events.GENERATION_AFTER_COMMANDS, xdPreClean);
eventOn(tavern_events.GENERATION_AFTER_COMMANDS, xdInject);

/* 按 DDL 逐行自检：sqlite 灌表会挡下哪几行，这里就报哪几行（ISSUES.md A4）。
 *
 * 【为什么要有】数据库插件有 sqlite 和 native 两种存储模式。native 下一条 CHECK 都不查，
 * 填表 AI 写错的格子照样落盘；可之后每次重载，插件都要把表整张灌进 sqlite（hydrate），
 * 碰到一行违反 CHECK / UNIQUE / NOT NULL 就整库起不来、退回 native，从此**永远**起不来
 * ——追平、填表的 SQL 路径一直被拦着。2026-09-24 真机就是这么卡死的。
 * 所以坏格子得在它落盘的那一拍就认出来：db-guard.js 每次表格落盘后拿这里的 ddlAudit 查一遍。
 *
 * 【照哪份 DDL】每张表自己带的 sourceData.ddl，就是插件 hydrate 时执行的那一份；
 * 老聊天里存的旧版 DDL 也按它自己的算。
 *
 * 【语义和插件的 hydrate 一致】（插件源码 generateInserts / escapeValue / _loadSheet）
 *   - 按表里的顺序一行一条 INSERT；表头按「列名 / 列注释 / 行号」认列。
 *   - null 是 NULL，'' 是空串：CHECK(category IN (...)) 对 '' 不过、对 NULL 放行。
 *   - 纯数字的格子不加引号插进去，TEXT 列存的是数字转回来的文本（'007' 存成 '7'）。
 *   - code_index 先 trim + NFKC + 转大写（插件的 FIELD_NORMALIZERS）。
 *   - CHECK 算出 NULL 算过，只有明确为假才挡（三值逻辑）。
 *   - UNIQUE 不管 NULL；重复时挡的是后插的那一行。
 *   - row_id：空的插件当已删除、跳过；不是整数、重复都挡。
 * test_ddl.mjs 拿 node:sqlite 按同一份 DDL 逐行对拍，两边的结论必须一致。
 *
 * 只认 tables.py 用得到的写法：列约束 PRIMARY KEY / NOT NULL / UNIQUE / CHECK / DEFAULT，
 * 表约束 CHECK / UNIQUE(...)；表达式里的 = == <> != < <= > >=、[NOT] IN、[NOT] GLOB、
 * IS [NOT] NULL、AND / OR / NOT、COALESCE / IFNULL / TRIM、括号。
 * 认不出的那条约束**跳过**、记进 skipped，不会误报；build_card.py 断言本卡的 DDL 一条都不跳。
 */
const DdlCheck = (() => {
  /* ---------- 词法 ---------- */

  function lex(sql) {
    const out = [];
    let i = 0;
    while (i < sql.length) {
      const c = sql[i];
      if (/\s/.test(c)) { i++; continue; }
      if (c === '-' && sql[i + 1] === '-') { const j = sql.indexOf('\n', i); i = j < 0 ? sql.length : j; continue; }
      if (c === '/' && sql[i + 1] === '*') { const j = sql.indexOf('*/', i + 2); i = j < 0 ? sql.length : j + 2; continue; }
      if (c === "'") {
        let j = i + 1, s = '';
        for (; j < sql.length; j++) {
          if (sql[j] !== "'") { s += sql[j]; continue; }
          if (sql[j + 1] === "'") { s += "'"; j++; continue; }
          break;
        }
        out.push({ t: 'str', v: s });
        i = j + 1;
        continue;
      }
      const q = { '"': '"', '`': '`', '[': ']' }[c];
      if (q) {
        const j = sql.indexOf(q, i + 1);
        const end = j < 0 ? sql.length : j;
        out.push({ t: 'id', v: sql.slice(i + 1, end), u: sql.slice(i + 1, end).toUpperCase(), quoted: true });
        i = end + 1;
        continue;
      }
      let m = /^\d+(\.\d+)?/.exec(sql.slice(i, i + 40));
      if (m) { out.push({ t: 'num', v: m[0] }); i += m[0].length; continue; }
      m = /^[A-Za-z_][A-Za-z0-9_]*/.exec(sql.slice(i, i + 200));
      if (m) { out.push({ t: 'id', v: m[0], u: m[0].toUpperCase() }); i += m[0].length; continue; }
      const two = sql.slice(i, i + 2);
      if (['<>', '!=', '==', '<=', '>=', '||'].indexOf(two) > -1) { out.push({ t: 'op', v: two }); i += 2; continue; }
      out.push({ t: 'op', v: c });
      i++;
    }
    return out;
  }

  /* ---------- 语法：CREATE TABLE 拆成列和约束，约束里的表达式建成树 ---------- */

  class Unsupported extends Error { }

  function parser(toks) {
    let p = 0;
    const peek = (k = 0) => toks[p + k];
    const isKw = (w, k = 0) => { const t = peek(k); return !!t && t.t === 'id' && !t.quoted && t.u === w; };
    const isOp = (o, k = 0) => { const t = peek(k); return !!t && t.t === 'op' && t.v === o; };
    const take = () => toks[p++];
    const need = o => { if (!isOp(o)) throw new Unsupported('缺 ' + o); p++; };

    function primary() {
      const t = peek();
      if (!t) throw new Unsupported('表达式不完整');
      if (t.t === 'str') { p++; return { k: 'lit', v: t.v }; }
      if (t.t === 'num') { p++; return { k: 'lit', v: t.v }; }
      if (isOp('(')) { p++; const e = expr(); need(')'); return e; }
      if (isOp('-') && peek(1) && peek(1).t === 'num') { p += 2; return { k: 'lit', v: '-' + toks[p - 1].v }; }
      if (t.t === 'id') {
        if (!t.quoted && t.u === 'NULL') { p++; return { k: 'lit', v: null }; }
        if (isOp('(', 1)) {
          const fn = t.u;
          if (['COALESCE', 'IFNULL', 'TRIM'].indexOf(fn) < 0) throw new Unsupported('函数 ' + fn);
          p += 2;
          const args = [];
          if (!isOp(')')) { args.push(expr()); while (isOp(',')) { p++; args.push(expr()); } }
          need(')');
          return { k: 'fn', fn: fn, args: args };
        }
        if (!t.quoted && ['CASE', 'SELECT', 'EXISTS', 'CAST', 'LIKE', 'REGEXP', 'MATCH', 'BETWEEN', 'COLLATE'].indexOf(t.u) > -1) {
          throw new Unsupported(t.u);
        }
        p++;
        return { k: 'col', v: t.v };
      }
      throw new Unsupported('认不出「' + t.v + '」');
    }
    function cmp() {
      const a = primary();
      let neg = false;
      if (isKw('NOT') && (isKw('IN', 1) || isKw('GLOB', 1))) { p++; neg = true; }
      if (isKw('IN')) {
        p++; need('(');
        const list = [];
        if (!isOp(')')) { list.push(expr()); while (isOp(',')) { p++; list.push(expr()); } }
        need(')');
        return { k: 'in', a: a, list: list, neg: neg };
      }
      if (isKw('GLOB')) { p++; return { k: 'glob', a: a, pat: primary(), neg: neg }; }
      if (isKw('IS')) {
        p++;
        const not = isKw('NOT') ? (p++, true) : false;
        if (!isKw('NULL')) throw new Unsupported('IS 后面只认 NULL');
        p++;
        return { k: 'isnull', a: a, neg: not };
      }
      if (peek() && peek().t === 'op' && ['=', '==', '<>', '!=', '<', '<=', '>', '>='].indexOf(peek().v) > -1) {
        const op = take().v;
        return { k: 'cmp', op: op === '==' ? '=' : op === '!=' ? '<>' : op, a: a, b: primary() };
      }
      if (peek() && peek().t === 'op' && peek().v === '||') throw new Unsupported('||');
      return a;
    }
    function not() {
      if (isKw('NOT')) { p++; return { k: 'not', a: not() }; }
      return cmp();
    }
    function and() {
      let a = not();
      while (isKw('AND')) { p++; a = { k: 'and', a: a, b: not() }; }
      return a;
    }
    function expr() {
      let a = and();
      while (isKw('OR')) { p++; a = { k: 'or', a: a, b: and() }; }
      return a;
    }
    return { expr, peek, take, isKw, isOp, need, pos: () => p, at: n => { p = n; } };
  }

  /** 列注释：和插件的 parseDDLColumnComments 同一个正则，逐行认 `列名 …… -- 注释`。 */
  function comments(body) {
    const m = new Map();
    body.split('\n').forEach(line => {
      const hit = line.trim().match(/^([^\s,()]+)\s+.*?--\s*(.+?)\s*,?\s*$/);
      if (hit) m.set(hit[1], hit[2]);
    });
    return m;
  }

  /** 按顶层逗号切开括号里的定义（引号、括号、注释里的逗号不算）。 */
  function splitDefs(body) {
    const out = [];
    let depth = 0, cur = '', i = 0;
    while (i < body.length) {
      const c = body[i];
      if (c === '-' && body[i + 1] === '-') { const j = body.indexOf('\n', i); const e = j < 0 ? body.length : j; cur += body.slice(i, e); i = e; continue; }
      if (c === "'") {
        let j = i + 1;
        for (; j < body.length; j++) { if (body[j] === "'") { if (body[j + 1] === "'") { j++; continue; } break; } }
        cur += body.slice(i, j + 1); i = j + 1; continue;
      }
      if (c === '(') depth++;
      if (c === ')') depth--;
      if (c === ',' && depth === 0) { out.push(cur); cur = ''; i++; continue; }
      cur += c; i++;
    }
    if (cur.trim()) out.push(cur);
    return out;
  }

  /** DDL -> { table, cols: [{name, comment, pk, notNull, unique, hasDefault}], checks: [{expr, sql, cols}],
   *           uniques: [[列名…]], skipped: [人话] }。解析不了整条 CREATE TABLE 就返回 null。 */
  function parse(ddl) {
    const text = String(ddl || '');
    const head = /CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?([^\s(]+)\s*\(/i.exec(text);
    if (!head) return null;
    // 找配对的右括号（跳过引号和注释）
    let depth = 0, end = -1;
    for (let i = head.index + head[0].length - 1; i < text.length; i++) {
      const c = text[i];
      if (c === '-' && text[i + 1] === '-') { const j = text.indexOf('\n', i); i = j < 0 ? text.length : j; continue; }
      if (c === "'") { const j = text.indexOf("'", i + 1); i = j < 0 ? text.length : j; continue; }
      if (c === '(') depth++;
      if (c === ')' && --depth === 0) { end = i; break; }
    }
    if (end < 0) return null;
    const body = text.slice(head.index + head[0].length, end);
    const notes = comments(body);
    const out = { table: head[1].replace(/["`[\]]/g, ''), cols: [], checks: [], uniques: [], skipped: [] };

    const checkAt = (P, src, owner) => {
      // P 停在 CHECK 上
      const start = P.pos();
      P.take();
      try {
        P.need('(');
        const e = P.expr();
        P.need(')');
        out.checks.push({ expr: e, sql: src, owner: owner || null });
      } catch (err) {
        if (!(err instanceof Unsupported)) throw err;
        out.skipped.push((owner ? owner + ' 的 ' : '') + 'CHECK（' + err.message + '）');
        // 跳过这对括号
        P.at(start + 1);
        let d = 0;
        do {
          const t = P.take();
          if (!t) break;
          if (t.t === 'op' && t.v === '(') d++;
          if (t.t === 'op' && t.v === ')') d--;
        } while (d > 0);
      }
    };

    splitDefs(body).forEach(def => {
      const toks = lex(def);
      if (!toks.length) return;
      const P = parser(toks);
      const src = def.replace(/--[^\n]*/g, '').replace(/\s+/g, ' ').trim();
      if (P.isKw('CONSTRAINT')) { P.take(); P.take(); }
      if (P.isKw('CHECK')) { checkAt(P, src); return; }
      if (P.isKw('UNIQUE') || (P.isKw('PRIMARY') && P.isKw('KEY', 1))) {
        if (P.isKw('PRIMARY')) P.take();
        P.take();
        try {
          P.need('(');
          const names = [];
          while (P.peek() && !P.isOp(')')) { const t = P.take(); if (t.t === 'id') names.push(t.v); }
          P.need(')');
          out.uniques.push(names);
        } catch (err) { out.skipped.push('表级 UNIQUE（' + err.message + '）'); }
        return;
      }
      if (P.isKw('FOREIGN')) { out.skipped.push('FOREIGN KEY'); return; }
      const name = P.take().v;
      const col = { name: name, comment: notes.get(name) || null, pk: false, notNull: false, unique: false, hasDefault: false, type: '' };
      if (P.peek() && P.peek().t === 'id' && !P.isKw('PRIMARY') && !P.isKw('NOT') && !P.isKw('UNIQUE') && !P.isKw('CHECK') && !P.isKw('DEFAULT')) {
        col.type = P.take().u;
      }
      while (P.peek()) {
        if (P.isKw('PRIMARY') && P.isKw('KEY', 1)) { P.take(); P.take(); col.pk = true; continue; }
        if (P.isKw('NOT') && P.isKw('NULL', 1)) { P.take(); P.take(); col.notNull = true; continue; }
        if (P.isKw('UNIQUE')) { P.take(); col.unique = true; continue; }
        if (P.isKw('CHECK')) { checkAt(P, src, name); continue; }
        if (P.isKw('DEFAULT')) {
          P.take(); col.hasDefault = true;
          if (P.isOp('(')) { let d = 0; do { const t = P.take(); if (t.v === '(') d++; if (t.v === ')') d--; } while (d > 0 && P.peek()); }
          else P.take();
          continue;
        }
        if (P.isKw('CONSTRAINT')) { P.take(); P.take(); continue; }
        out.skipped.push(name + ' 列上的「' + P.take().v + '」');
        break;
      }
      out.cols.push(col);
    });
    return out;
  }

  /* ---------- 取值：格子里的东西 -> sqlite 里存成的样子 ---------- */

  const INT64_MAX = BigInt('9223372036854775807');

  /** 插件 escapeValue：纯数字不加引号插；TEXT 列把数字再转回文本。 */
  function stored(v, colName) {
    if (v === null || v === undefined) return null;
    let s = typeof v === 'string' ? v : String(v);
    if (colName && colName.toLowerCase() === 'code_index') s = s.trim().normalize('NFKC').toUpperCase();
    if (/^-?\d+$/.test(s)) {
      const n = BigInt(s);
      if (n <= INT64_MAX && n >= -INT64_MAX - BigInt(1)) return n.toString();
      return s;
    }
    if (/^-?\d+\.\d+$/.test(s)) {
      const n = Number(s);
      return Number.isInteger(n) ? n.toFixed(1) : String(n);
    }
    return s;
  }

  /* ---------- 求值：三值逻辑，null = 未知 ---------- */

  function globRe(pat) {
    let re = '', i = 0;
    const chars = Array.from(pat);
    while (i < chars.length) {
      const c = chars[i];
      if (c === '*') re += '[\\s\\S]*';
      else if (c === '?') re += '[\\s\\S]';
      else if (c === '[') {
        let j = i + 1, neg = false, cls = '';
        if (chars[j] === '^') { neg = true; j++; }
        if (chars[j] === ']') { cls += '\\]'; j++; }
        while (j < chars.length && chars[j] !== ']') {
          const ch = chars[j];
          cls += (ch === '-' && cls && chars[j + 1] !== ']') ? '-' : ch.replace(/[\\\]^-]/g, '\\$&');
          j++;
        }
        if (j >= chars.length) return null;          // 没闭合：sqlite 当它什么都不匹配
        re += '[' + (neg ? '^' : '') + cls + ']';
        i = j;
      } else re += c.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
      i++;
    }
    return new RegExp('^' + re + '$', 'u');
  }

  function evalE(e, row) {
    switch (e.k) {
      case 'lit': return e.v;
      case 'col': return Object.prototype.hasOwnProperty.call(row, e.v) ? row[e.v] : null;
      case 'fn': {
        const a = e.args.map(x => evalE(x, row));
        if (e.fn === 'COALESCE' || e.fn === 'IFNULL') { for (const v of a) if (v !== null) return v; return null; }
        return a[0] === null ? null : String(a[0]).replace(/^ +| +$/g, '');     // TRIM
      }
      case 'cmp': {
        const a = evalE(e.a, row), b = evalE(e.b, row);
        if (a === null || b === null) return null;
        // 本卡带约束的列全是 TEXT，数字字面量跟它比也按文本比（sqlite 的列亲和性），一律按文本比
        const c = a < b ? -1 : a > b ? 1 : 0;
        return { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[e.op];
      }
      case 'in': {
        const a = evalE(e.a, row);
        if (a === null) return e.list.length ? null : e.neg;
        let unk = false;
        for (const x of e.list) {
          const v = evalE(x, row);
          if (v === null) { unk = true; continue; }
          if (v === a) return !e.neg;
        }
        return unk ? null : e.neg;
      }
      case 'glob': {
        const a = evalE(e.a, row), pat = evalE(e.pat, row);
        if (a === null || pat === null) return null;
        const re = globRe(pat);
        const hit = !!re && re.test(a);
        return e.neg ? !hit : hit;
      }
      case 'isnull': { const a = evalE(e.a, row); return e.neg ? a !== null : a === null; }
      case 'not': { const a = truth(evalE(e.a, row)); return a === null ? null : !a; }
      case 'and': {
        const a = truth(evalE(e.a, row)), b = truth(evalE(e.b, row));
        if (a === false || b === false) return false;
        return a === null || b === null ? null : true;
      }
      case 'or': {
        const a = truth(evalE(e.a, row)), b = truth(evalE(e.b, row));
        if (a === true || b === true) return true;
        return a === null || b === null ? null : false;
      }
    }
    return null;
  }

  /** sqlite 的真假：NULL 未知；数字看是不是 0；文本按开头能读出的数字算（'abc' 是 0）。 */
  function truth(v) {
    if (v === null) return null;
    if (typeof v === 'boolean') return v;
    const m = /^\s*[+-]?(\d+(\.\d*)?|\.\d+)/.exec(String(v));
    return m ? Number(m[0]) !== 0 : false;
  }

  function colsOf(e, acc) {
    if (!e) return acc;
    if (e.k === 'col') { if (acc.indexOf(e.v) < 0) acc.push(e.v); return acc; }
    ['a', 'b', 'pat'].forEach(k => colsOf(e[k], acc));
    (e.args || []).concat(e.list || []).forEach(x => colsOf(x, acc));
    return acc;
  }

  /* ---------- 审一张表 ---------- */

  function label(cols, head, col) {
    const c = cols.find(x => x.name === col);
    return (c && c.comment) || col;
  }

  function show(v) {
    if (v === null) return '（空）';
    const s = String(v);
    if (!s) return '（空串）';
    return '「' + (Array.from(s).length > 24 ? Array.from(s).slice(0, 24).join('') + '…' : s) + '」';
  }

  /** 一张表 -> 问题清单。每条 {sheetKey, sheet, rowId, name, pos, rule, why, rows?}：
   *  rowId 是被挡的那一行，pos 是它在 content 里的下标；rule 是这条约束的稳定编号（比较「这一轮新冒出来的」用）；
   *  why 是一句人话；UNIQUE 撞车时 rows 带上跟它撞的那一行。 */
  function auditSheet(sheetKey, sheet, skippedOut) {
    const issues = [];
    const content = sheet && Array.isArray(sheet.content) ? sheet.content : null;
    if (!content || !content.length) return issues;
    const def = parse(sheet.sourceData && sheet.sourceData.ddl);
    const name = sheet.name || sheetKey;
    if (!def) return issues;                      // 没有 DDL：插件走全 TEXT 的兜底表，没有约束
    def.skipped.forEach(s => skippedOut.push(name + '：' + s));
    const heads = content[0].map((h, i) => (h === null || h === undefined) ? (i === 0 ? 'row_id' : '') : String(h).trim());
    const at = {};
    def.cols.forEach(c => {
      const i = heads.findIndex(h => h && (h === c.name || (c.name === 'row_id' && h === '行号') || (c.comment && h === c.comment)));
      if (i > -1) at[c.name] = i;
    });
    const missing = def.cols.filter(c => at[c.name] === undefined && (c.pk || (c.notNull && !c.hasDefault)));
    if (missing.length) {
      issues.push({ sheetKey, sheet: name, rowId: null, name: '', rule: 'head',
        why: '表头里找不到「' + missing.map(c => c.comment || c.name).join('、') + '」这几列' });
      return issues;
    }
    const pk = def.cols.find(c => c.pk);
    const pkCol = pk ? pk.name : null;
    // 行的标签：第一列业务列（姓名 / 物品名称 / 编码索引……），玩家在面板里一眼认得出
    const tagCol = def.cols.find(c => !c.pk && at[c.name] !== undefined);
    const uniq = def.cols.filter(c => c.unique || c.pk).map(c => [c.name]).concat(def.uniques);
    const seen = uniq.map(() => new Map());

    for (let r = 1; r < content.length; r++) {
      const raw = content[r];
      if (!Array.isArray(raw)) continue;
      const row = {};
      def.cols.forEach(c => { row[c.name] = at[c.name] === undefined ? null : stored(raw[at[c.name]], c.name); });
      const rawId = pkCol ? raw[at[pkCol]] : null;
      const rowId = rawId === null || rawId === undefined ? '' : String(rawId).trim();
      if (pkCol && !rowId) continue;              // 插件把空 row_id 的行当已删除，灌表前就扔了
      const tag = tagCol ? String(raw[at[tagCol.name]] == null ? '' : raw[at[tagCol.name]]).trim() : '';
      const base = { sheetKey, sheet: name, rowId, name: tag, pos: r };
      const bad = [];

      if (pkCol && !/^-?\d+$/.test(rowId)) bad.push({ rule: 'pk', why: '行号「' + rowId + '」不是整数' });
      def.cols.forEach(c => {
        if (c.notNull && !c.pk && row[c.name] === null) bad.push({ rule: 'nn:' + c.name, why: '「' + label(def.cols, heads, c.name) + '」不能空着' });
      });
      def.checks.forEach((ck, k) => {
        if (truth(evalE(ck.expr, row)) !== false) return;
        const cs = colsOf(ck.expr, []);
        let why;
        if (ck.expr.k === 'in' && ck.expr.a.k === 'col' && !ck.expr.neg) {
          why = '「' + label(def.cols, heads, ck.expr.a.v) + '」只能填 '
            + ck.expr.list.map(x => evalE(x, {})).join('/') + '，填的是' + show(row[ck.expr.a.v]);
        } else if (ck.expr.k === 'glob' && ck.expr.a.k === 'col' && !ck.expr.neg) {
          why = '「' + label(def.cols, heads, ck.expr.a.v) + '」' + show(row[ck.expr.a.v]) + '不合格式 ' + evalE(ck.expr.pat, {});
        } else {
          why = cs.map(c => label(def.cols, heads, c) + show(row[c])).join('、') + '，这几格不合规则';
        }
        bad.push({ rule: 'ck' + k, why: why, sql: ck.sql });
      });
      // 前面的约束挡住了，这一行根本进不了表，后面的行也就不会跟它撞 UNIQUE
      if (!bad.length) {
        uniq.forEach((cs, k) => {
          const vals = cs.map(c => row[c]);
          if (vals.some(v => v === null)) return;
          const key = JSON.stringify(vals);
          const hit = seen[k].get(key);
          if (hit) {
            bad.push({ rule: 'uq:' + cs.join(',') + ':' + key, rows: [hit],
              why: cs.length === 1 && cs[0] === pkCol
                ? '行号 ' + rowId + ' 重复了'
                : '「' + cs.map(c => label(def.cols, heads, c)).join('+') + '」' + show(vals.join(' / ')) + '和行号 ' + hit + ' 那一行重复' });
          }
        });
        if (!bad.length) uniq.forEach((cs, k) => {
          const vals = cs.map(c => row[c]);
          if (!vals.some(v => v === null)) seen[k].set(JSON.stringify(vals), rowId);
        });
      }
      bad.forEach(b => issues.push(Object.assign({}, base, b)));
    }
    return issues;
  }

  /** 整份表格数据（exportTableAsJson 的返回）-> { issues, skipped } */
  function audit(data) {
    const issues = [], skipped = [];
    if (!data || typeof data !== 'object') return { issues, skipped };
    Object.keys(data).filter(k => k.startsWith('sheet_')).forEach(k => {
      auditSheet(k, data[k], skipped).forEach(x => issues.push(x));
    });
    return { issues, skipped };
  }

  /** 问题的身份：同一张表、同一行、同一条约束算同一个问题（比较「这一轮新冒出来的」用） */
  function key(x) { return x.sheetKey + '\u0001' + x.rowId + '\u0001' + x.rule; }

  return { parse, audit, key, stored };
})();

/* 数据库插件（可选）：表格落盘后按 DDL 逐行自检，不合规的行撤回，请玩家重新填表。
 *
 * 2026-09-25 起卡不再依赖数据库插件：关系、物品、功法都在 MVU 里（src/data_field.py、
 * src/mvu-data.js），模板只剩纪要表（src/tables.py）。本文件以前还管三件事，随那几张表一起删了：
 *   主角守门（角色表里主角那一行删掉）、关系表的折叠 / 展开注入 / 级联删、关系表里主体是主角的行删掉。
 * 「主角只当客体」「有角色才有关系」两条规矩还在，挪到 src/mvu-data.js 对 stat_data.关系 做。
 *
 * **没装数据库时这个文件什么都不做**：拿不到 AutoCardUpdaterAPI，挂回调那一步等一分钟就放弃；
 * 换聊天 / 生成完那两趟扫描进门就返回。不报错、不弹提示、不注入任何东西。
 *
 * ────────────────────────────────────────────────────────────────────────────
 * 【按 DDL 自检，不合规的行撤回】（2026-09-24 加，ISSUES.md A4）
 *
 * native 模式没有 CHECK，填表 AI 写错的格子照样落盘；之后每次重载插件都要把表灌进 sqlite，
 * 一行不合 DDL 整库就起不来，从此永远卡在 native。纪要表的 DDL 有两条 CHECK
 * （编码索引 AMxxxx、时间跨度的格式），所以每一趟扫描都拿 src/ddl-check.js
 * 把整份表按各表自己的 DDL 逐行查一遍（tableAudit）：
 *   - 跟「上一次查过的表」（base）比，**新冒出来的**不合规行，按 row_id 撤回到 base 里的样子：
 *     base 里有这一行就改回去，没有就删掉。然后弹一条提示，带「重新填表」按钮
 *     （插件的 manualUpdate：先清掉范围内的增量再重填，自带确认框）。
 *   - base 里本来就有的（老存档、换了聊天、插件回放了楼层）只提示、不动——
 *     撤回不了，也不该替玩家猜哪一版是对的。
 * base 是上一趟扫描查完以后的整份表，也就是下一次填表之前的样子。不用插件的「填表开始」
 * 回调另拍：那个回调没有注销接口，换一次聊天就在插件里攥住一个死 iframe；base 就算旧一点
 * 也无妨——撤回只动被挡的那几行，本轮填对的照样留着。
 * 换聊天时脚本的 iframe 整个重建，base 从空开始；插件切聊天会先把表清空，读不到就不查，
 * 所以 base 不会拍到上一个聊天的表。chatKey 再对一次，双保险。
 *
 * 【不碰世界书】世界书条目会凭空消失（见 book-heal.js）：所有写入方都是「读一份 -> 改 -> 整本写回」。
 * 插件每轮填完表本来就要整本写一次，这里要是再让它当场重新导出，就等于在它刚写完的那一秒里
 * 再插一次整本回写。所以写一律带 skipNotify：只改表、落进聊天存档，一次世界书写入都不加。
 *
 * 【读写一律走插件的行级 API，不用 SQL】插件有两种存储模式：`sqlite` 和 `native`。
 * native 下 `executeSqlMutation` 直接拒绝，`querySql` 只在插件自己的 sqlite 会话活着时才存在。
 * 玩家的插件是什么模式我们管不着，所以：读走 `exportTableAsJson()`，
 * 写走 `updateRow` / `deleteRow`，两种模式都认。
 *
 * 酒馆助手脚本跑在 iframe 里，换聊天时 iframe 会被拆掉，回调得自己注销，
 * 否则插件手里攥着一个死掉的函数。
 */
(() => {
  const LOG = '[原著指导]';
  let busy = false;
  let again = false;
  let retry = 0;
  const RETRY_MAX = 5;      // 读不到表就隔 4 秒再试，最多 5 次（约 20 秒）

  function api() {
    try { return window.parent.AutoCardUpdaterAPI || null; } catch (e) { return null; }
  }

  function txt(v) { return v == null ? '' : String(v).trim(); }

  /** 读一张表 -> `[{_i, 列名: 值}]`；`_i` 是行在表里的位置（表头是 0），行级 API 按它定位。
   *
   *  **为什么不用 `querySql`**：它是运行时门控的，只在插件自己的 sqlite 会话活着时才存在，
   *  页面平时（加载完、生成前）一律是 `undefined`；`storageMode` 是 `native` 时更是压根没有
   *  sqlite。`exportTableAsJson()` 同步、零耗时、两种模式下随时可用，拿的是同一份表数据。 */
  function exportRows(a, sheetName, head) {
    try {
      if (!a || typeof a.exportTableAsJson !== 'function') return null;
      const tpl = a.exportTableAsJson();
      if (!tpl || typeof tpl !== 'object' || typeof tpl.then === 'function') return null;
      const sheet = Object.keys(tpl).map(k => tpl[k]).find(x => x && x.name === sheetName);
      const content = sheet && Array.isArray(sheet.content) ? sheet.content : null;
      if (!content || !content.length) return null;
      const cols = content[0].map(c => head[String(c).trim()] || String(c).trim());
      return content.slice(1).map((r, i) => {
        const one = { _i: i + 1 };
        cols.forEach((c, k) => { one[c] = r[k] == null ? '' : r[k]; });
        return one;
      });
    } catch (e) { return null; }
  }

  /* 写一律走插件的行级 API：`updateRow` / `deleteRow`，两种存储模式都认。
   *
   * **别用 `executeSqlMutation`**：`native` 模式下它直接拒绝
   * （「SQL 变更仅在 SQLite 模式下可用」），而玩家的插件是什么模式我们管不着——
   * 2026-09-21 真机踩到：测试机的 sqlite 初始化失败、插件自己退回 native，
   * 当时的折叠 / 级联删 / 主角守门整套**静默失效**，一行报错都没有。
   *
   * `skipNotify`：只改表、落进聊天存档，**不**让插件当场重新导出世界书（见文件头「不碰世界书」）。*/

  /** 按 **row_id** 找它此刻在表里的位置。位置会随删行变动，所以每次写之前现查。 */
  function posOf(a, sheet, head, rowId) {
    const rows = exportRows(a, sheet, head);
    if (!rows) return null;
    const hit = rows.find(r => txt(r.row_id) === txt(rowId));
    return hit ? hit._i : null;
  }

  async function rowPut(a, sheet, head, rowId, data) {
    const i = posOf(a, sheet, head, rowId);
    if (i == null) { console.warn(`${LOG} 「${sheet}」里找不到 row_id=${rowId} 那一行，跳过`); return false; }
    try {
      if (await a.updateRow({ tableName: sheet, rowIndex: i, data: data, skipNotify: true })) return true;
      console.warn(`${LOG} 改「${sheet}」row_id=${rowId} 失败`);
    } catch (e) { console.warn(`${LOG} 改「${sheet}」row_id=${rowId} 出错`, e); }
    return false;
  }

  /** 删行**按 row_id 逐条删，每条删之前重新定位**。
   *  行级 API 只认「位置」，而删掉一行，它后面所有行的位置都会往前挪一格——
   *  拿一份旧快照里的位置去删，删掉的就是别人。（2026-09-21 离线测试床上真删错过。） */
  async function rowDel(a, sheet, head, rowIds) {
    let n = 0;
    for (const id of Array.from(new Set(rowIds.map(txt))).filter(Boolean)) {
      const i = posOf(a, sheet, head, id);
      if (i == null) continue;                 // 已经没了：别人删过或本轮重入，跳过就是幂等
      try {
        if (await a.deleteRow({ tableName: sheet, rowIndex: i, skipNotify: true })) { n++; continue; }
        // 返回 false 多半是「刚才还在、真去删时已经没了」（插件自己重载了表，或同一轮的
        // 前一步删过）。再查一眼：真没了就当删成功，别打一条吓人的「失败」。
        if (posOf(a, sheet, head, id) == null) { n++; continue; }
        console.warn(`${LOG} 删「${sheet}」row_id=${id} 失败`);
      } catch (e) { console.warn(`${LOG} 删「${sheet}」row_id=${id} 出错`, e); }
    }
    return n;
  }

  /* ---------- 按 DDL 自检：新冒出来的不合规行撤回，请玩家重新填表（见文件头） ---------- */

  let base = null;          // {chat, data, keys}：上一次查过的整份表，和它当时已有的问题
  let replayed = false;     // 那次落盘是插件回放楼层（persisted:false），不是新写的
  let saidSig = '';         // 上一次弹的提示，一样就不再弹

  function chatKey() {
    try { return String(SillyTavern.getContext().chatId || ''); } catch (e) { return ''; }
  }

  function snap(a) {
    try {
      const data = JSON.parse(JSON.stringify(a.exportTableAsJson()));
      return { chat: chatKey(), data: data, keys: new Set(DdlCheck.audit(data).issues.map(DdlCheck.key)) };
    } catch (e) { return null; }
  }

  function sheetOf(data, key) { return data && data[key] && Array.isArray(data[key].content) ? data[key] : null; }

  /** 一行在 base 里的样子 -> updateRow 的 data（中文表头作键，null 原样写回：'' 过不了 IN 约束） */
  function cellsOf(sheet, rowId) {
    const head = sheet.content[0];
    const row = sheet.content.slice(1).find(r => Array.isArray(r) && txt(r[0]) === rowId);
    if (!row) return null;
    const data = {};
    head.forEach((h, i) => { if (i > 0 && h != null && txt(h)) data[txt(h)] = row[i] === undefined ? null : row[i]; });
    return data;
  }

  function sameRow(a, b) { return JSON.stringify(a) === JSON.stringify(b); }

  /** 新冒出来的不合规行撤回到 base 里的样子。返回撤回了几行。
   *  UNIQUE 撞车时两行都看：谁跟 base 不一样撤谁（可能是新插的那行，也可能是被改成重名的旧行）。 */
  async function undoRows(a, fresh) {
    const cur = a.exportTableAsJson();
    const todo = new Map();            // sheetKey\u0001rowId -> {sheetKey, rowId}
    fresh.forEach(x => [x.rowId].concat(x.rows || []).forEach(id => {
      if (id) todo.set(x.sheetKey + '\u0001' + id, { sheetKey: x.sheetKey, rowId: id });
    }));
    const puts = [], dels = new Map();
    todo.forEach(t => {
      const was = sheetOf(base.data, t.sheetKey), now = sheetOf(cur, t.sheetKey);
      if (!was || !now) return;
      const before = cellsOf(was, t.rowId), after = cellsOf(now, t.rowId);
      if (!after || (before && sameRow(before, after))) return;
      if (before) puts.push({ name: now.name, rowId: t.rowId, data: before });
      else dels.set(now.name, (dels.get(now.name) || []).concat([t.rowId]));
    });
    let n = 0;
    for (const p of puts) if (await rowPut(a, p.name, {}, p.rowId, p.data)) n++;
    for (const [name, ids] of dels) n += await rowDel(a, name, {}, ids);
    return n;
  }

  function esc(s) {
    return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  }

  /** 右上角一条不自己消失的提示，带「重新填表」按钮 */
  function tell(title, list, tail) {
    const lines = list.slice(0, 4).map(x => x.sheet + (x.name ? ' · ' + x.name : '') + '：' + x.why);
    if (list.length > 4) lines.push('……一共 ' + list.length + ' 处');
    const a = api();
    const can = !!a && typeof a.manualUpdate === 'function';
    const html = '<div style="white-space:pre-wrap">' + esc(lines.join('\n')) + '</div>'
      + '<div style="margin-top:6px">' + esc(tail) + '</div>'
      + (can ? '<button class="menu_button" data-cn-refill style="margin-top:6px">重新填表</button>' : '');
    try {
      const t = toastr.error(html, title, { timeOut: 0, extendedTimeOut: 0, closeButton: true, tapToDismiss: false, escapeHtml: false });
      if (can && t && t.find) {
        t.find('[data-cn-refill]').on('click', () => {
          try { toastr.clear(t); } catch (e) { }
          Promise.resolve(a.manualUpdate()).catch(e => console.warn(`${LOG} 重新填表出错`, e));
        });
      }
    } catch (e) { }
  }

  async function tableAudit(a) {
    const chat = chatKey();
    const got = DdlCheck.audit(a.exportTableAsJson());
    if (got.skipped.length) console.warn(`${LOG} DDL 里有认不出的约束，这几条没查：${got.skipped.join('；')}`);
    let issues = got.issues;
    // 能撤回的只有「这一轮新冒出来的」：同一个聊天、base 里没有、也不是插件回放楼层带回来的
    const fresh = base && base.chat === chat && !replayed ? issues.filter(x => !base.keys.has(DdlCheck.key(x))) : [];
    replayed = false;
    let undone = 0;
    if (fresh.length) {
      console.warn(`${LOG} 表格里新写进 ${fresh.length} 处不合 DDL 的格子，sqlite 灌表会被挡：`
        + fresh.map(x => `${x.sheet} row_id=${x.rowId}：${x.why}${x.sql ? '（' + x.sql + '）' : ''}`).join('；'));
      undone = await undoRows(a, fresh);
      issues = DdlCheck.audit(a.exportTableAsJson()).issues;
    }
    const left = issues;
    base = snap(a);
    const sig = (undone ? 'u' + undone + ':' : '') + left.map(DdlCheck.key).join('|');
    if (sig === saidSig) return;
    saidSig = sig;
    if (undone) {
      console.info(`${LOG} 已撤回 ${undone} 行不合规的数据`);
      tell('填表写错了，已撤回', fresh, '这几行不合表格规则，留着会让数据库的 SQLite 起不来。');
    } else if (left.length) {
      console.warn(`${LOG} 表格里有 ${left.length} 处不合 DDL 的格子：`
        + left.map(x => `${x.sheet} row_id=${x.rowId}：${x.why}`).join('；'));
      tell('表格里有不合规的行', left, '留着会让数据库的 SQLite 起不来。重新填表，或者在数据库面板里改掉。');
    }
  }

  /* ---------- 扫描 ---------- */

  /** 插件把表加载进来了没有：导出里至少有一张带表头的表 */
  function loaded(a) {
    try {
      const tpl = a.exportTableAsJson();
      if (!tpl || typeof tpl !== 'object' || typeof tpl.then === 'function') return false;
      return Object.keys(tpl).some(k => tpl[k] && Array.isArray(tpl[k].content) && tpl[k].content.length);
    } catch (e) { return false; }
  }

  async function sweep() {
    if (busy) { again = true; return; }
    const a = api();
    // 没装数据库（或者还没起来）：什么都不做。门只认读接口，两种存储模式下它都在
    if (!a || typeof a.exportTableAsJson !== 'function') return;
    // 插件把表加载进来要一会儿：CHAT_CHANGED 之后那一趟常常什么都读不到
    // （native 模式尤其明显）。读不到就隔几秒再来，别把这一整局都放过去。
    if (!loaded(a)) {
      if (retry < RETRY_MAX) { retry++; setTimeout(sweep, 4000); }
      else if (retry === RETRY_MAX) { retry++; console.info(`${LOG} 一直读不到表格，先不扫了，等下一次填表`); }
      return;
    }
    retry = 0;
    busy = true;
    try {
      await tableAudit(a);
    } catch (e) {
      console.warn(`${LOG} 表格自检出错，这一轮先放过`, e);
    } finally {
      busy = false;
      if (again) { again = false; setTimeout(sweep, 500); }
    }
  }

  // 插件在自己的调用栈里同步调回调，别在里面直接改表，挪到下一拍。
  // persisted:false 是插件回放楼层 / 恢复运行时（删楼、切 swipe），不是新写进来的，自检只提示不撤回
  const onUpdate = meta => {
    if (meta && meta.persisted === false) replayed = true;
    setTimeout(sweep, 300);
  };

  function hook() {
    const a = api();
    if (!a || typeof a.registerTableUpdateCallback !== 'function') return false;
    a.registerTableUpdateCallback(onUpdate);
    window.addEventListener('pagehide', () => {
      try { a.unregisterTableUpdateCallback(onUpdate); } catch (e) { }
    });
    return true;
  }

  // 插件是全局脚本，可能比本卡的脚本晚起来，等它一会儿；一分钟还没有就是没装，不再等
  let tries = 0;
  (function wait() {
    if (hook()) { sweep(); return; }
    if (++tries < 60) setTimeout(wait, 1000);
  })();
  // 换聊天、重 roll 之后插件会按楼层重放表格，再扫一遍
  eventOn(tavern_events.CHAT_CHANGED, () => setTimeout(sweep, 3000));
  eventOn(tavern_events.GENERATION_ENDED, () => setTimeout(sweep, 3000));

  // 离线测试床用的出口（node 里跑自检，见 test_ddl.mjs）。真机上没人读它。
  try { window.__canonDb = { sweep, tableAudit, DdlCheck }; } catch (e) { }
})();

/* ===== MVU 变量更新 · 玩家的破限配置（内核）=====
 *
 * 齿轮面板「破限」：除了「MVU 内置」，其余都是玩家自己建的配置，每份 = 名字 + 三格
 *   head 前置（资料区前面，系统）/ link 衔接（聊天记录前面，系统）/ prefill 预填（回复开头，AI），
 * 空着的那格不进预设，三格全空不让存。每份对应一份酒馆预设「MC.prefix + 名字 + MC.suffix」。
 * 结构和预置配置都在 src/mvu_jb.py 的 custom_data()，构建时填进下面的 MC。
 *
 * 预置配置（MC.defaults，目前一份「小猫之神」，id xiaomao）：读的时候列表里没有这个 id、也没有同名的、
 * 也没被删过（dismissed 里没有它），就补进列表开头。玩家存过一次整张列表，它就跟着存下来，
 * 之后改的是玩家那份，卡更新也不拿默认值盖回去；删掉它就把 id 记进 dismissed，以后不再补。
 * 它的预设名正好是旧版卡内置小猫之神生成的那份，MVU 正指着那份时面板点亮它，加载时按它对账。
 *
 * 存两处，形状一样 {v: 2, items: [{id, name, head, link, prefill, at}], dismissed?: [删掉的预置配置 id]}：
 *   - 「原著指导」脚本的脚本变量里 MC.key 这一格（跟 canon / canon_edits 同一袋，只动这一格）；
 *   - 「同步进卡」写到卡的 data.extensions[MC.ext]（走 writeExtensionField，多一个 synced 时间戳），
 *     导出卡、换装新卡后从这里恢复。
 * 读的时候脚本变量里有这一格就用它（删光了也算有：留一个空列表，免得删掉的又从卡里冒出来），没有才用卡里那份。
 * 旧的单份形状（v1：{head, link, prefill}，09-26 上午那版）读到就转成一份叫「自定义」的配置——
 * 预设名跟当时那份「仙子·变量更新（自定义）」是同一个。
 *
 * 这个文件嵌两处：原著指导脚本（mvu-jb.js 前面，生成预设）和状态栏齿轮面板（mvu-api.js 前面，编辑）。 */
const MC = {"prefix": "仙子·变量更新（", "suffix": "）", "key": "mvu_custom_jb", "ext": "xz_mvu_custom", "slots": {"head": ["xz-cu-head", "自定义·前置", "system"], "link": ["xz-cu-link", "自定义·衔接", "system"], "prefill": ["xz-cu-prefill", "自定义·预填", "assistant"]}, "skeleton": [{"fill": "head"}, {"id": "xz-info-open", "name": "资料区开", "enabled": true, "position": {"type": "relative"}, "role": "system", "content": "\u003cadditional_information>"}, {"id": "personaDescription", "name": "Persona Description", "enabled": true, "position": {"type": "relative"}, "role": "system"}, {"id": "charDescription", "name": "Char Description", "enabled": true, "position": {"type": "relative"}, "role": "system"}, {"id": "worldInfoBefore", "name": "World Info (before)", "enabled": true, "position": {"type": "relative"}, "role": "system"}, {"id": "worldInfoAfter", "name": "World Info (after)", "enabled": true, "position": {"type": "relative"}, "role": "system"}, {"id": "xz-info-close", "name": "资料区关", "enabled": true, "position": {"type": "relative"}, "role": "system", "content": "\u003c/additional_information>"}, {"fill": "link"}, {"id": "chatHistory", "name": "Chat History", "enabled": true, "position": {"type": "relative"}, "role": "system"}, {"id": "xz-ask", "name": "任务", "enabled": true, "position": {"type": "relative"}, "role": "user", "content": "遵循\u003cmust>指令"}, {"fill": "prefill"}], "defaults": []};
const MC_KEYS = Object.keys(MC.slots);
const MC_V1_NAME = '自定义';
const MC_BAD_NAME = /[\\/:*?"<>|]/;     // 预设名会落成文件名，这几个字符不许用

function mcIsObj(o) { return !!o && typeof o === 'object' && !Array.isArray(o); }

/** 一份配置规整成 {id, name, head, link, prefill, at} */
function mcNormItem(o) {
  const out = { id: mcIsObj(o) && typeof o.id === 'string' ? o.id : '', name: mcIsObj(o) && typeof o.name === 'string' ? o.name.trim() : '' };
  MC_KEYS.forEach(k => { out[k] = mcIsObj(o) && typeof o[k] === 'string' ? o[k] : ''; });
  out.at = mcIsObj(o) && typeof o.at === 'string' ? o.at : '';
  return out;
}

/** 三格都空（只有空白也算空） */
function mcEmpty(o) { return MC_KEYS.every(k => !String((o && o[k]) || '').trim()); }

/** 两份配置内容一样不一样（名字 + 三格，不看 id、时间） */
function mcSameItem(a, b) {
  a = mcNormItem(a); b = mcNormItem(b);
  return a.name === b.name && MC_KEYS.every(k => a[k] === b[k]);
}

function mcDismissed(o) {
  return mcIsObj(o) && Array.isArray(o.dismissed) ? o.dismissed.filter(x => typeof x === 'string' && x) : [];
}

/** 整张列表规整成 {v: 2, items[, dismissed]}。认不出来的返回 null（= 这一处没有）。
 *  v1 单份：有内容就转成一份「自定义」，空壳当没有 */
function mcNorm(o) {
  if (!mcIsObj(o)) return null;
  if (Array.isArray(o.items)) {
    const seen = new Set(), names = new Set(), items = [];
    o.items.forEach((x, i) => {
      const it = mcNormItem(x);
      if (!it.name || names.has(it.name)) return;
      if (!it.id || seen.has(it.id)) it.id = 'c' + i + '-' + it.name;
      seen.add(it.id); names.add(it.name);
      items.push(it);
    });
    const out = { v: 2, items };
    const dis = mcDismissed(o);
    if (dis.length) out.dismissed = [...new Set(dis)];
    return out;
  }
  const one = mcNormItem(Object.assign({}, o, { id: 'v1', name: MC_V1_NAME }));
  return mcEmpty(one) ? null : { v: 2, items: [one] };
}

/** 两张列表内容一样不一样（顺序、名字、三格、删过的预置配置；不看时间） */
function mcSame(a, b) {
  const pick = s => JSON.stringify([((s && s.items) || []).map(it => [it.id, it.name].concat(MC_KEYS.map(k => it[k]))),
    ((s && s.dismissed) || []).slice().sort()]);
  return pick(a) === pick(b);
}

/** 脚本变量里那张（没有这一格 = null） */
function mcFromVars(scriptId) {
  try { return mcNorm((TavernHelper.getVariables({ type: 'script', script_id: scriptId }) || {})[MC.key]); }
  catch (e) { return null; }
}

/** 卡里 data.extensions 那张（没有 = null） */
function mcFromCard() {
  try {
    const c = TavernHelper.getCharData('current');
    return mcNorm(c && c.data && c.data.extensions && c.data.extensions[MC.ext]);
  } catch (e) { return null; }
}

/** 补上预置配置：列表里没有这个 id、没有同名的、也没被删过的，按 MC.defaults 的顺序补在开头 */
function mcWithDefaults(s) {
  const base = mcNorm(s) || { v: 2, items: [] };
  const dis = new Set(base.dismissed || []);
  const add = (MC.defaults || []).filter(d => !dis.has(d.id) && !base.items.some(it => it.id === d.id || it.name === d.name))
    .map(d => mcNormItem(d));
  if (!add.length) return base;
  return Object.assign({}, base, { items: add.concat(base.items) });
}

/** 读：脚本变量优先，其次卡里，都没有就只有预置配置。都补上预置配置。返回 {s, from: 'vars' | 'card' | ''} */
function mcLoad(scriptId) {
  const v = mcFromVars(scriptId);
  if (v) return { s: mcWithDefaults(v), from: 'vars' };
  const c = mcFromCard();
  if (c) return { s: mcWithDefaults(c), from: 'card' };
  return { s: mcWithDefaults(null), from: '' };
}

/** 整张存进脚本变量，只动 MC.key 这一格（删光了也留一个空列表） */
function mcSaveAll(scriptId, s) {
  const x = mcNorm(s) || { v: 2, items: [] };
  TavernHelper.updateVariablesWith(v => { v = v || {}; v[MC.key] = x; return v; }, { type: 'script', script_id: scriptId });
  return x;
}

function mcPresetName(name) { return MC.prefix + name + MC.suffix; }
function mcFind(s, id) { return ((s && s.items) || []).find(it => it.id === id) || null; }
/** MVU 现在指着的预设名 -> 哪份配置（对不上就 null） */
function mcByPreset(s, preset) { return ((s && s.items) || []).find(it => mcPresetName(it.name) === preset) || null; }

/** 新增或更新一份（form 带 id 就是更新，不带就是新增）。纯函数，不写盘。
 *  返回 {s: 新列表, item: 存下的那份, old: 更新前那份（新增是 null）} 或 {err: 给人看的一句话} */
function mcUpsert(s, form) {
  const list = (mcNorm(s) || { v: 2, items: [] }).items.slice();
  const it = mcNormItem(form);
  if (!it.name) return { err: '先起个名字。' };
  if (MC_BAD_NAME.test(it.name)) return { err: '名字里不能有 \\ / : * ? " < > | 这几个字符。' };
  if (it.name.length > 30) return { err: '名字太长了，30 个字以内。' };
  if (mcEmpty(it)) return { err: '先写提示词，至少一格。' };
  if (list.some(x => x.name === it.name && x.id !== it.id)) return { err: '已经有一份叫「' + it.name + '」的了。' };
  const i = it.id ? list.findIndex(x => x.id === it.id) : -1;
  const old = i >= 0 ? list[i] : null;
  if (!old) it.id = 'c' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  it.at = old && mcSameItem(old, it) ? old.at : new Date().toISOString();
  if (old) list[i] = it; else list.push(it);
  const out = { v: 2, items: list };
  const dis = mcDismissed(s);
  if (dis.length) out.dismissed = dis;
  return { s: out, item: it, old: old };
}

/** 删一份。纯函数，返回新列表。删的是预置配置就把 id 记进 dismissed，以后不再补 */
function mcRemove(s, id) {
  const base = mcNorm(s) || { v: 2, items: [] };
  const out = { v: 2, items: base.items.filter(it => it.id !== id) };
  const dis = (base.dismissed || []).slice();
  if ((MC.defaults || []).some(d => d.id === id) && !dis.includes(id)) dis.push(id);
  if (dis.length) out.dismissed = dis;
  return out;
}

/** 按骨架拼出一份配置的预设 prompts：玩家那几格填进去，空的整条去掉 */
function mcPrompts(o) {
  const x = mcNormItem(o);
  const out = [];
  MC.skeleton.forEach(p => {
    if (!p.fill) { const row=JSON.parse(JSON.stringify(p)); if(typeof row.content==='string')row.content=(globalThis.parent?.XZ_PROMPTS || globalThis.XZ_PROMPTS)?.render('mvu.skeleton.'+p.id,[]) ?? row.content; out.push(row); return; }
    const text = x[p.fill];
    if (!text.trim()) return;
    const [id, name, role] = MC.slots[p.fill];
    out.push({ id, name, enabled: true, position: { type: 'relative' }, role, content: text });
  });
  return out;
}

/* MVU 额外模型解析的两件事。
 *
 * 1. 摘掉混进后台请求里的函数工具。
 *    酒馆开着函数调用时，ToolManager 会给**每一个** chat completion 请求挂上已注册的工具，
 *    MVU 走酒馆助手 generateRaw 发的变量更新也不例外。小猫之神的「防截断2.0」绑了一个
 *    game_content 工具，模型一看到它就把 <UpdateVariable> 塞进工具参数里，正文是空的，
 *    MVU 找不到更新块，三次重试全挂。2026-09-18 拿同一份请求重放：带工具 content 为空、
 *    finish_reason = tool_calls；不带工具直接吐出 <UpdateVariable>。
 *    所以在 CHAT_COMPLETION_SETTINGS_READY 上认出这类后台请求，把工具摘掉。
 *    MVU 自己的「工具调用」应答格式会传 tool_choice: 'required'，那种不动。
 *
 *    数据库插件的**填表**请求同样中招。2026-09-22 真机抓包：填表请求发去的是酒馆后端
 *    /api/backends/chat-completions/generate，所以也被挂上了 game_content
 *    （tool_choice: auto，custom_prompt_post_processing: merge_tools）。卡里的填表提示词
 *    又明写「也不调用任何函数工具」，模型两头讨好——不发 tool_call，却用文本模仿出
 *    工具那个 {content: string} 的壳，整份回复成了 ```json {"content":"…<tableEdit>…"}```，
 *    <tableEdit> 里的引号全带反斜杠，插件解析 insertRow(0, {\"0\":…}) 在 position 1 炸掉，
 *    15 条命令 100% 失败，五张表一行没落。所以填表请求也一起摘。
 *
 * 2. 破限配置。齿轮面板里除了「MVU 内置」，都是配置列表里的（内核 src/mvu-custom.js，构建时排在这个文件前面；
 *    预置一份可编辑的「小猫之神」，其余玩家自己建）。面板存好配置后发 XZ_MVU_JB_CUSTOM（带配置 id），这里在预设列表里生成 / 更新
 *    「仙子·变量更新（<配置名>）」，面板再把 MVU 指过去。内容没变就不重写。
 *    MVU 正指着某份配置的预设时，每次加载对一次账（换装新卡后脚本变量没了，从卡里 data.extensions 那份恢复）。
 *    旧版卡生成的「仙子·变量更新（小猫之神）」跟预置配置同名，按预置配置对账（内容更新成现在那份）。
 *    MVU 指着的预设对不上任何一份配置，一概不碰。
 */
(() => {
  const SCRIPT_ID = "c0a17e6d-9b4f-4d21-8f3a-7e15cbb20d91";   // 「原著指导」脚本，破限配置存在它的脚本变量里
  const MVU_TASK = '紧急变量更新任务';
  /* 填表请求的特征串。挑「【填表AI】」而不是 <tableEdit> / insertRow，理由：
   *  - 它来自数据库插件**默认**填表提示词第 [4] 段的开头「你是【填表AI】」，
   *    src/fill_prompt.py 正是拿这句当补丁锚点（RULES_MARK），不打补丁也在，稳定；
   *  - 它只活在填表提示词里。卡的正文、世界书、开场白、预设里一个字都没有
   *    （latest/ 那张基准卡 grep 不到），所以主生成请求不可能带上它；
   *  - <tableEdit> / insertRow 则会出现在模型**吐出来的**填表结果里，那玩意儿可能
   *    随楼层正文进聊天记录，再被主生成请求带回去，摘掉主生成的 game_content
   *    会伤到正文（防截断2.0 要求正文走那个工具）——所以不能用它们当特征。
   * 2026-09-22 四份真机请求比对：填表请求 2 处命中，主生成 / 时间召回 / MVU 均 0 处。 */
  const FILL_TASK = '【填表AI】';

  function textOf(m) {
    const c = m && m.content;
    if (typeof c === 'string') return c;
    if (Array.isArray(c)) return c.map(x => (x && typeof x.text === 'string' ? x.text : '')).join('');
    return '';
  }

  eventOn(tavern_events.CHAT_COMPLETION_SETTINGS_READY, data => {
    if (!data || !Array.isArray(data.tools) || !data.tools.length) return;
    if (data.tool_choice === 'required') return;
    if (!Array.isArray(data.messages)) return;
    const hit = data.messages.some(m => {
      const t = textOf(m);
      return t.includes(MVU_TASK) || t.includes(FILL_TASK);
    });
    if (!hit) return;
    delete data.tools;
    delete data.tool_choice;
  });

  function mvuCfg() {
    try { return _.get(SillyTavern, 'extensionSettings.mvu_settings.额外模型解析配置') || null; } catch (e) { return null; }
  }

  function samePrompts(a, b) {
    const pick = ps => JSON.stringify((ps || []).map(p => [p.id, p.role, p.content || '', p.enabled !== false]));
    return pick(a) === pick(b);
  }

  /** 一份配置的预设：按存的内容生成 / 更新；内容没变不重写，三格全空不生成。返回预设在不在 */
  async function ensureItem(it) {
    if (!it || mcEmpty(it)) return false;
    const name = mcPresetName(it.name);
    const want = mcPrompts(it);
    if (TavernHelper.getPresetNames().includes(name)) {
      try { if (samePrompts(TavernHelper.getPreset(name).prompts, want)) return true; } catch (e) { /* 读不了就重写 */ }
    }
    const preset = { settings: TavernHelper.getPreset('in_use').settings, prompts: want, prompts_unused: [], extensions: {} };
    await TavernHelper.createOrReplacePreset(name, preset);
    return TavernHelper.getPresetNames().includes(name);
  }

  // 面板存好一份配置：生成它的预设
  eventOn('XZ_MVU_JB_CUSTOM', async id => {
    try { await ensureItem(mcFind(mcLoad(SCRIPT_ID).s, id)); } catch (e) { console.error('[状态更新] 生成破限预设失败', e); }
  });

  // 加载时对账：MVU 正指着哪份配置的预设，就按存的内容更新它
  const c = mvuCfg();
  if (c && c.破限方案 === '使用其他预设') {
    const it = mcByPreset(mcLoad(SCRIPT_ID).s, c.其他预设名称);
    if (it) ensureItem(it).catch(e => console.error('[状态更新] 更新破限预设失败', e));
  }
})();

/* ===== ▷ 推进 N 件 · 内核 =====
 * ▷ 的菜单列着原著指导从【当前】起的几件事，选「推进 N 件」= 往原著指导的设置里记一笔待办 cfg.pend = {chat, n}，
 * **不生成**。玩家照常打字发送，canon-inject.js 的 bindPend 把它绑到 AI 要写的那一楼（cfg.skip），
 * 那一轮允许跨时辰，把这 N 件连同玩家的行动发给 AI；只按正文实际完成的件数移动窗口。
 * 完成后若下一件还远，最多进入紧邻时辰并保留空档，不把时间直接拨到第 N+1 件。再选同一项取消。
 *
 * 2026-09-26 用户：「不允许存在 user 不输入信息还能推进的情况了」——原来的「推进一轮」（/trigger 续写一回合，
 * 玩家不发话）和点了就生成的「跳过 N 件」都删了，推进只能夹带玩家的话。
 *
 * 状态栏导航条上的 ▷（src/offstage.js）用这里的 pend / pending / upcoming；主页面的兜底条（src/rescue.js）
 * 只用 generating 判断「正在生成」。两边各跑在各自的 iframe 里，没法 import，构建时各嵌一份（build_card.py）。
 */
window.XZ_OFFSTAGE = (function () {
    const OS_CANON_ID = 'c0a17e6d-9b4f-4d21-8f3a-7e15cbb20d91';   // 原著指导脚本，设置存在它的脚本变量里

    let osGenFlag = false;   // 事件说酒馆正在生成（谁触发的都算）——别直接信，见 osGenerating
    const subs = [];         // 待办 / 忙闲一变就叫一声，入口自己去重画

    function notify() {
        for (const f of subs) { try { f(); } catch (e) { } }
    }

    /* 酒馆到底在不在生成。
     * 光听事件不行：装机酒馆上有东西每开一次聊天就 Generate 一次又早早返回，
     * 只发 GENERATION_STARTED、**不发 ENDED**（2026-09-21 实测，换一张没有本卡脚本的
     * 角色卡照样出现，不是卡干的）。只认事件的话这个标记就永远停在「在生成」上，
     * ▷ 从此再也点不动，而且灰得理直气壮——「正在生成，等这一轮写完」。
     * 所以再看一眼酒馆自己的停止按钮：它只在真有生成在飞的时候露出来。
     * 两个都说在跑才算在跑；按钮找不着（酒馆改版）就退回只认事件。 */
    function osStopShown() {
        try {
            const w = window.parent;
            const el = w.document.getElementById('mes_stop');
            if (!el) return null;
            return w.getComputedStyle(el).display !== 'none';
        } catch (e) { return null; }
    }

    function osGenerating() {
        if (!osGenFlag) return false;
        const shown = osStopShown();
        return shown === null ? true : shown;
    }

    // 常驻选择属于当前聊天；旧存档没记这一格时默认关闭。
    function osRepeat() {
        try { return TavernHelper.getVariables({ type: 'chat' })?.canon_game?.advanceRepeat === true; }
        catch (e) { return false; }
    }
    function osRepeatCount() {
        try {
            const g = TavernHelper.getVariables({ type: 'chat' })?.canon_game;
            return g?.advanceRepeat === true && Number.isInteger(g.advanceCount) && g.advanceCount >= 0 ? g.advanceCount : null;
        } catch (e) { return null; }
    }
    function osSaveRepeat(enabled, n) {
        TavernHelper.updateVariablesWith(v => {
            v = v || {};
            v.canon_game = Object.assign({}, v.canon_game || {}, { advanceRepeat: !!enabled, advanceCount: n });
            return v;
        }, { type: 'chat' });
    }
    function osSetRepeat(enabled) {
        const n = osPending();
        try {
            osSaveRepeat(enabled, enabled ? n : null);
            // 关闭常驻后，已选件数只留给下一条玩家消息。
            osPend(n);
            notify();
            return true;
        } catch (e) { console.error('[推进] 常驻设置没存上', e); return false; }
    }

    /** 当前待办优先；发过之后从当前聊天读取常驻件数。0 = 铺垫，null = 未选择。 */
    function osPending() {
        try {
            const v = TavernHelper.getVariables({ type: 'script', script_id: OS_CANON_ID }) || {};
            const p = (v.canon || {}).pend;
            return p && Number.isInteger(p.n) && p.n >= 0 && p.chat === (SillyTavern.getContext().chatId || '') ? p.n : osRepeatCount();
        } catch (e) { return null; }
    }

    /** 选「推进 N 件」：显式待办，bindPend 将其标记为手动跨时辰；常驻后续不会带这笔待办。n = null 取消。 */
    function osPend(n) {
        if (n !== null && (!Number.isInteger(n) || n < 0)) return false;
        try {
            const chat = SillyTavern.getContext().chatId || '';
            TavernHelper.updateVariablesWith(v => {
                v = v || {};
                v.canon = Object.assign({}, v.canon || {}, { pend: n !== null ? { chat: chat, n: n } : null });
                return v;
            }, { type: 'script', script_id: OS_CANON_ID });
            if (osRepeat()) osSaveRepeat(true, n);
            notify();
            return true;
        } catch (e) {
            console.error('[推进] 推进件数记不上', e);
            try { toastr.error('推进件数没记上', '推进'); } catch (e2) { }
            return false;
        }
    }

    /** 原著指导窗口从【当前】起往后的几件事（给菜单列出来选），读不到就是空 */
    function osUpcoming(max) {
        try {
            const v = TavernHelper.getVariables({ type: 'script', script_id: OS_CANON_ID }) || {};
            const cfg = v.canon || {};
            // 开没开按这一局的聊天变量 canon_game，没记才用整张卡那一格（同 canon-inject.js 的 gameOn）
            const g = (TavernHelper.getVariables({ type: 'chat' }) || {}).canon_game;
            const on = g && typeof g.enabled === 'boolean' ? g.enabled : cfg.enabled !== false;
            if (!on || !cfg.start) return [];
            // 故事线是番外（只有自由模式才算数）：没有时间轴，▷ 的「推进 N 件」用不上，列空的
            const free = !!(g && g.free === true);
            const ser = free ? ((cfg.series === 'ex' || cfg.series === 'mr') ? cfg.series : 'main') : 'main';
            if (ser !== 'main') return [];
            const c = TavernHelper.getCharData('current');
            let cn = (c && c.data && c.data.extensions && c.data.extensions.canon) || null;
            // 卡瘦身：事件库不在卡里时用 cnEvents 那份（没就位就先空着，▷ 菜单等它下好）
            if (cn && window.cnEvents) cn = window.cnEvents.canonOf(cn);
            // 原著页上改过的标题（状态栏里原著页那个模块挂出来的；主页面兜底条没有，就用卡内版本）
            if (cn && typeof ceApply === 'function') cn = ceApply(cn, ceLoad(OS_CANON_ID));
            else if (cn && typeof window.xzCeApply === 'function') cn = window.xzCeApply(cn);
            const evs = (cn && cn.events) || [];
            const ex = new Set(cfg.excluded || []);
            let k = evs.findIndex(e => e.eid === cfg.start);
            if(k<0 && Object.prototype.hasOwnProperty.call(evs._ceFallback||{},cfg.start)) k=evs.findIndex(e=>e.i>=evs._ceFallback[cfg.start]);
            if (k < 0) return [];
            return evs.slice(k).filter(e => !ex.has(e.eid)).slice(0, max || 8);
        } catch (e) { return []; }
    }

    try {
        eventOn(tavern_events.GENERATION_STARTED, () => { osGenFlag = true; notify(); });
        eventOn(tavern_events.GENERATION_ENDED, () => { osGenFlag = false; notify(); });
        eventOn(tavern_events.GENERATION_STOPPED, () => { osGenFlag = false; notify(); });
    } catch (e) { /* 事件名拿不到就算了 */ }

    return {
        repeat: osRepeat,
        setRepeat: osSetRepeat,
        pend: osPend,
        pending: osPending,
        upcoming: osUpcoming,
        generating: osGenerating,
        onChange: (f) => { subs.push(f); },
    };
})();

/* ===== 重试状态更新 · 内核 =====
 *
 * 一个入口既是**指示灯**也是**重试按钮**：
 *
 *   转圈  变量更新还在跑（或刚生成完、MVU 还没回来）—— 不可点
 *   ✓ 绿  这一楼的变量更新成功了 —— 不可点
 *   ↻ 红  失败了 —— 可以点，点一次重试一次
 *
 * 点一次就只跑一次。成功就变绿锁住；还是失败就回到红色，可以再点。
 *
 * 两处入口共用这一份：状态栏导航条上的 ↻（src/retry.js），和最后一楼没渲染
 * 状态栏时主页面上的兜底条（src/rescue.js）。两边各跑在各自的 iframe 里，
 * 没法 import，构建时各嵌一份（build_card.py）——所以行为只在这个文件里改。
 * 不同的只有「盯哪一楼」和「怎么画」，attach() 的时候各自给。
 *
 * ## 怎么知道成没成功
 *
 * 额外模型解析成功时，MVU 会把 `<UpdateVariable><Analysis>…` 追加回楼层正文；
 * 它的重试逻辑开头又会**先把旧的剥掉**。所以「这一楼正文里有没有 <UpdateVariable>」
 * 就是干净的判据，不用去猜变量有没有变——有些回合本来就没什么可变的。
 * 2026-09-25 起再加一条：卡自己的整理（src/mvu-txn.js 的事务）没走通、或者应答不完整被整轮放弃，
 * 会在 chat 变量「状态更新失败」里给这一楼（和当时的 swipe）记一笔——有这一笔也算失败，照样红、能点。
 * 重跑成功了事务自己把这一笔删掉。
 *
 * ## 怎么触发 MVU
 *
 * MVU 面板里本来就有「重试额外模型解析」：剥掉旧的 <UpdateVariable> ->
 * 把变量回滚到上一楼 -> 重跑一次额外模型解析。但它是 MVU 的内部函数，
 * Mvu 公开 API 里没有入口。好在它是**注册成酒馆助手脚本按钮事件**的：
 *     Fo.map(e => kt(getButtonEvent(e.name), e.function))
 * 而 getButtonEvent(name) = `${脚本id}_${getStringHash(name)}`，点击就是 emit 那个 id。
 * 所以算出同一个 id、eventEmit 一下就行。
 *
 * **这些按钮在卡里是 visible:false**，getAllEnabledScriptButtons() 拿不到
 * （button_map 按 visible 过滤）。但 MVU 注册监听是**无条件**的，跟可见性无关，
 * 隐藏的照样能用事件触发；拿不到就自己按脚本 id + 哈希算。
 *
 * ## 「随正文」更新时（2026-09-25 用户：「随正文模式没有重新生成的按钮」）
 *
 * 随正文（MVU 的「随AI输出」）没有单独的变量更新请求可以重跑，变量是跟着正文一起吐出来的。
 * 所以失败时 ↻ 照样可点，点了先确认，确认后对**最后一楼**重新生成，走酒馆助手的 triggerSlash：
 *   · 这一楼停在最后一个版本（swipe）上：`/swipe direction=right await=true`，跟点消息右边的箭头一样，
 *     在最后一个版本后面新生成一个，旧的都留着，左右箭头还切得回去（ST 1.18 的 swipeChatCallback：
 *     最后一个版本再往右是 overswipe，AI 消息的默认行为就是生成新的一个；await=true 等生成完）；
 *   · 停在前面的版本上：往右只是切到下一个现成的版本，生成不了新的，只能 `/regenerate`——
 *     它会把这一楼连同**全部版本**删掉再生成，所以确认框写明「会删掉这一楼全部 N 个版本」。
 *   （2026-09-25 以前一律 /regenerate，玩家攒了几个版本的楼一点就全没了。）
 * 生成完 MVU 照常随正文解析，灯按新的一楼重新点。历史楼层照旧不可点；独立 API 那条路不变。
 * 确认框用酒馆自己的弹窗（getContext().callGenericPopup，画在主页面上，手机 WebView 里也弹得出来），
 * 拿不到才退回入口自己给的 opt.confirm / window.confirm。
 */
window.XZ_RETRY = (function () {
    const RT_BTN = '重试额外模型解析';
    // 转圈多久就给结论。MVU 跑一次独立 API 通常十几秒，20 秒够看到正常情况；
    // 更长的它内部重试要是还没回来，也先落红让按钮可用，别把人干晾着——
    // 后台监视还留着，它晚点成功了照样自动翻绿。
    const RT_SPIN = 20000;
    const RT_POLL = 500;
    const RT_IDLE_POLL = 2000;   // 落红之后的后台监视间隔
    const RT_EXTRA = '额外模型解析';
    const RT_REGEN_ASK = '重新生成这一楼？会新写一个版本，现在的版本都留着（消息左右的箭头切得回来）。';
    const RT_SWIPE_CMD = '/swipe direction=right await=true';
    const RT_REGEN_CMD = '/regenerate await=true';
    /** 停在前面的版本上：只能整楼重来 */
    function rtRegenAllAsk(n, at) {
        return '重新生成这一楼？这一楼有 ' + n + ' 个版本，现在停在第 ' + (at + 1) + ' 个，不是最后一个——'
            + '重新生成会删掉这一楼全部 ' + n + ' 个版本，再写一个新的。';
    }

    /** 和酒馆 public/scripts/utils.js 里的 getStringHash 逐行一致（cyrb53） */
    function rtHash(str, seed = 0) {
        if (typeof str !== 'string') return 0;
        let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
        for (let i = 0, ch; i < str.length; i++) {
            ch = str.charCodeAt(i);
            h1 = Math.imul(h1 ^ ch, 2654435761);
            h2 = Math.imul(h2 ^ ch, 1597334677);
        }
        h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
        h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
        return 4294967296 * (2097151 & h2) + (h1 >>> 0);
    }

    function rtMethod() {
        try { return _.get(SillyTavern, 'extensionSettings.mvu_settings.更新方式') || ''; }
        catch (e) { return ''; }
    }
    function rtHasUpdate(id) {
        try {
            const m = (TavernHelper.getChatMessages(id) || []).at(-1);
            return String(_.get(m, 'message', '')).includes('<UpdateVariable>');
        } catch (e) { return false; }
    }
    /** 卡自己的整理在这一楼（当前这个 swipe）记过失败没有（src/mvu-txn.js 的 XZ_TXN_KEY） */
    function rtFailed(id) {
        try {
            const v = TavernHelper.getVariables({ type: 'chat' }) || {};
            const hit = v['状态更新失败'] && v['状态更新失败'][id];
            if (!hit) return '';
            const m = (TavernHelper.getChatMessages(id) || []).at(-1);
            if(!m)return '';
            const swipe = Number(_.get(m, 'swipe_id', 0) || 0);
            if(hit.scope!==undefined||hit.signature!==undefined){
                const c=SillyTavern.getContext(),row=c.chat?.[Number(id)];if(!row||row.is_user||row.is_system)return '';
                const scope=JSON.stringify([c.characters?.[c.characterId]?.avatar||'',c.chatId||'',c.chatMetadata?.xz_book_save?.localId||'']);
                const signature=JSON.stringify([String(row.mes||'').replace(/<UpdateVariable\b[^>]*>[\s\S]*?(?:<\/UpdateVariable>|$)/gi,'').trim(),row.send_date??null,row.name??null]);
                if(hit.scope!==undefined&&hit.scope!==scope||hit.signature!==undefined&&hit.signature!==signature)return '';
            }
            return Number(hit.swipe || 0) === swipe ? String(hit.why || '卡里的整理没走通') : '';
        } catch (e) { return ''; }
    }
    /** 这一楼有几个版本（swipe）、停在第几个：{n, at}。读不出来给 null */
    function rtSwipes(id) {
        try {
            const m = (TavernHelper.getChatMessages(id, { include_swipes: true }) || []).at(-1);
            if (!m) return null;
            const n = Array.isArray(m.swipes) && m.swipes.length ? m.swipes.length : 1;
            const at = Math.min(n - 1, Math.max(0, Number(m.swipe_id) || 0));
            return { n: n, at: at };
        } catch (e) { return null; }
    }
    /** 重新生成这一楼该用哪条命令、怎么问：停在最后一个版本上就新 swipe 一个，不然只能整楼 /regenerate */
    function rtRegenPlan(id) {
        const sw = rtSwipes(id);
        if (sw && sw.at === sw.n - 1) return { cmd: RT_SWIPE_CMD, ask: RT_REGEN_ASK, sw: sw };
        if (sw) return { cmd: RT_REGEN_CMD, ask: rtRegenAllAsk(sw.n, sw.at), sw: sw };
        return { cmd: RT_REGEN_CMD, ask: '重新生成这一楼？这一楼有几个版本读不出来，重新生成会删掉这一楼的全部版本。', sw: null };
    }

    /** 这一楼算成功：MVU 写回了 <UpdateVariable>，卡里的整理也没记失败 */
    function dualFloor(id) { const api=window.parent?.XZ_REINCARNATION_MVU;return api?.active?.()?api.floorState?.(Number(id)):null; }
    function rtDone(id) { const dual=dualFloor(id);return dual ? dual.done : rtHasUpdate(id) && !rtFailed(id); }
    function rtEventId() {
        try {
            const all = TavernHelper.getAllEnabledScriptButtons() || {};
            for (const list of Object.values(all)) {
                const hit = (list || []).find(b => b && b.button_name === RT_BTN);
                if (hit) return hit.button_id;
            }
        } catch (e) { /* 拿不到就往下走 */ }
        for (const type of ['character', 'global', 'preset']) {
            let trees = [];
            try { trees = TavernHelper.getScriptTrees({ type }) || []; } catch (e) { continue; }
            for (const tree of trees) {
                const scripts = tree && tree.type === 'folder' ? (tree.scripts || []) : [tree];
                for (const s of scripts) {
                    if (!s || !s.enabled || !s.id) continue;
                    if ((_.get(s, 'button.buttons', []) || []).some(b => b && b.name === RT_BTN))
                        return `${s.id}_${rtHash(RT_BTN)}`;
                }
            }
        }
        return null;
    }

    /** 问一句，回 true / false。酒馆自己的弹窗优先；ask 是入口给的备用（opt.confirm），再不行 window.confirm */
    async function rtConfirm(text, ask) {
        try {
            const ctx = SillyTavern.getContext ? SillyTavern.getContext() : SillyTavern;
            if (ctx && typeof ctx.callGenericPopup === 'function' && ctx.POPUP_TYPE) {
                const r = await ctx.callGenericPopup(text, ctx.POPUP_TYPE.CONFIRM);
                const yes = ctx.POPUP_RESULT ? ctx.POPUP_RESULT.AFFIRMATIVE : 1;
                return r === yes || r === true;
            }
        } catch (e) { console.warn('[重试状态更新] 酒馆的确认框弹不出来，换个办法问', e); }
        try { if (typeof ask === 'function') return !!(await ask(text)); } catch (e) { }
        try { return !!window.confirm(text); } catch (e) { return false; }
    }

    /** 接一个入口上来。
     *  opt.floor()  —— 现在盯的是哪一楼，拿不到给 -1
     *  opt.isLast() —— 那一楼是不是最后一楼（只有最后一楼能重试）
     *  opt.paint(state, can, title) —— 画：state ∈ wait | ok | bad，can 决定能不能点
     *  opt.confirm(text) —— 可选：酒馆的确认框拿不到时用它问（回 true / false）
     */
    function attach(opt) {
        let rtBusy = false;          // 正在等结果（自动等 or 手动重试），期间不可点
        let rtWatch = 0;             // 当前这轮的令牌，换楼/重开/再点时作废旧的

        const hub=()=>window.parent?.XZ_RETRY_MANAGER;
        let lastState='wait',lastCan=false,lastTitle='',closed=false;
        const originalPaint=opt.paint;
        const adapter={retry:()=>rtClick(),last:()=>opt.isLast(),closed:()=>closed,state:()=>lastState,busy:()=>rtBusy,title:()=>lastTitle};
        function repaint(){
            // A failed recall leaves the user's message last. Keep the latest
            // assistant status-bar entry usable for the shared chooser.
            let latestAssistant=false;try{latestAssistant=opt.floor()===SillyTavern.getContext().chat.findLastIndex(m=>!m.is_user&&!m.is_system);}catch{}
            const combined=(opt.isLast()||latestAssistant)&&hub()?.hasFailures();
            originalPaint(combined?'bad':lastState,combined?!hub()?.busy:lastCan,combined?'展开重试菜单：重试失败请求或指定任务':lastTitle);
        }
        opt.paint=(state,can,title)=>{lastState=state;lastCan=can;lastTitle=title;hub()?.register(adapter);repaint();};
        window.parent?.addEventListener?.('xz-retry-changed',repaint);
        window.addEventListener?.('pagehide',()=>{closed=true;hub()?.unregister(adapter);window.parent?.removeEventListener?.('xz-retry-changed',repaint);},{once:true});

        /** 按这一楼的实际情况把灯点上 */
        function rtSettle(floor) {
            const ok = rtDone(floor), why = rtHasUpdate(floor) ? rtFailed(floor) : '';
            const last = opt.isLast();
            if (ok) {
                opt.paint('ok', false, '这一楼的状态更新已完成');
                // 失败标记是异步写的，可能晚到一步：过一会儿再看一眼，记了失败就翻回红
                setTimeout(() => { if (rtHasUpdate(floor) && rtFailed(floor) && !rtBusy) rtSettle(floor); }, 1500);
                return true;
            }
            if (!last) { opt.paint('bad', false, '这一楼的状态更新没成功（只能重试最后一楼）'); return false; }
            const head = why ? '状态更新没走通（' + why + '）' : '状态更新没成功';
            if (rtMethod() !== RT_EXTRA)
                opt.paint('bad', true, head + '。当前是「随正文」更新，点击重新生成这一楼（正文会重写）');
            else
                opt.paint('bad', true, head + '，点击' + (why ? '重新跑一次' : '重试') + '（不重写正文）');
            return false;
        }

        /** 转圈等一小会儿；到点就给结论，之后交给后台监视 */
        async function rtWait(floor, token) {
            rtBusy = true;
            opt.paint('wait', false, '状态更新进行中…');
            const until = Date.now() + RT_SPIN;
            while (Date.now() < until) {
                if (token !== rtWatch) return;              // 换楼/又点了，这轮作废
                if (rtHasUpdate(floor)) { await new Promise(r => setTimeout(r, 300)); break; }   // 给失败标记一点落地的时间
                await new Promise(r => setTimeout(r, RT_POLL));
            }
            if (token !== rtWatch) return;
            rtBusy = false;
            if (rtSettle(floor)) return;
            rtIdleWatch(floor, token);
        }

        /** 落红之后继续低频看着：MVU 自己晚点成功了、或者你从 MVU 面板手动重试成功了，自动翻绿 */
        async function rtIdleWatch(floor, token) {
            while (token === rtWatch && !rtBusy) {
                await new Promise(r => setTimeout(r, RT_IDLE_POLL));
                if (token !== rtWatch || rtBusy) return;
                if (rtDone(floor)) { rtSettle(floor); return; }
            }
        }

        async function rtClick() {
            if (rtBusy) return;
            const floor = opt.floor();
            if (floor < 0 || !opt.isLast() || rtDone(floor)) return;
            if (dualFloor(floor)) { try { await window.parent.XZ_REINCARNATION_MVU.retry(); } finally { rtRefresh(); } return; }
            if (rtMethod() !== RT_EXTRA) return rtRegen(floor);
            const eventId = rtEventId();
            if (!eventId) {
                opt.paint('bad', true, '找不到 MVU 的「重试额外模型解析」入口，MVU 可能没在跑');
                return;
            }
            const token = ++rtWatch;
            rtBusy = true;
            opt.paint('wait', false, '正在重试状态更新…');
            try {
                await eventEmit(eventId);
            } catch (e) {
                console.error('[重试状态更新] 触发失败', e);
            }
            if (token !== rtWatch) return;
            rtBusy = false;
            // eventEmit 会 await MVU 的处理函数，回来时通常已经有结果了。
            // 成功就直接点绿；没成功再转着等一会儿——MVU 内部还有自己的「请求次数」次重试。
            if (rtDone(floor)) rtSettle(floor);
            else if (rtHasUpdate(floor)) { rtSettle(floor); rtIdleWatch(floor, token); }
            else rtWait(floor, token);
        }

        /** 随正文：问一句，确认了就重新生成最后一楼（新 swipe 一个，或者整楼重来，见文件头）。
         *  生成完的新楼由 MESSAGE_RECEIVED / MESSAGE_SWIPED 那条重新点灯 */
        async function rtRegen(floor) {
            rtBusy = true;                                   // 问的这会儿别让人连点出两个框
            const plan = rtRegenPlan(floor);
            let yes = false;
            try { yes = await rtConfirm(plan.ask, opt.confirm); } finally { rtBusy = false; }
            if (!yes) return;
            if (floor !== opt.floor() || !opt.isLast() || rtDone(floor)) return;   // 问的时候楼变了
            // 问的时候切了版本：问的是另一件事了（该删几个、删不删），不替玩家做主
            const now = rtSwipes(floor);
            if (JSON.stringify(now) !== JSON.stringify(plan.sw)) return;
            const token = ++rtWatch;
            rtBusy = true;
            opt.paint('wait', false, '正在重新生成这一楼…');
            try {
                await TavernHelper.triggerSlash(plan.cmd);
            } catch (e) {
                console.error('[重试状态更新] 重新生成没发出去', e);
            }
            if (token !== rtWatch) return;                   // 新楼到了、已经重新点过灯
            rtBusy = false;
            rtRefresh();
        }

        /** 重新点灯。没有 <UpdateVariable> 又是最后一楼，就先转一会儿——
         *  这一楼多半是刚生成完、MVU 的独立 API 还在路上，一上来就报红会误导。 */
        function rtRefresh() {
            const token = ++rtWatch;
            rtBusy = false;
            const floor = opt.floor();
            if (floor < 0) { opt.paint('bad', false, '拿不到楼层号'); return; }
            const dual=dualFloor(floor);
            if (dual) { rtBusy=dual.busy;opt.paint(dual.busy?'wait':dual.done?'ok':'bad',!dual.busy&&!dual.done&&opt.isLast(),dual.status||(dual.done?'这一楼的状态更新已完成':'请重试 MVU 状态更新'));return; }
            if (rtHasUpdate(floor) || !opt.isLast()) {           // 有 <UpdateVariable>：成没成看 rtSettle（含失败标记）
                if (!rtSettle(floor) && opt.isLast()) rtIdleWatch(floor, token);
                return;
            }
            rtWait(floor, token);
        }

        $(() => {
            // 打开时先按现状点灯；已经有 <UpdateVariable> 就直接绿，没有才去等
            rtRefresh();
            try {
                eventOn(tavern_events.MESSAGE_RECEIVED, () => { rtWatch++; rtBusy = false; rtRefresh(); });
                eventOn(tavern_events.CHAT_CHANGED, () => { rtWatch++; rtBusy = false; rtRefresh(); });
                eventOn(tavern_events.MESSAGE_SWIPED, () => { rtWatch++; rtBusy = false; rtRefresh(); });
            } catch (e) { /* 事件名拿不到就算了，按钮照样能点 */ }
        });
        window.parent?.addEventListener?.('xz-reincarnation-mvu-changed',rtRefresh);
        window.addEventListener?.('pagehide',()=>window.parent?.removeEventListener?.('xz-reincarnation-mvu-changed',rtRefresh),{once:true});

        return { click: () => hub()?hub().open(adapter):rtClick(), refresh: rtRefresh, busy: () => rtBusy };
    }

    return { attach, hash: rtHash, method: rtMethod, hasUpdate: rtHasUpdate, failed: rtFailed, done: rtDone, eventId: rtEventId, BTN: RT_BTN,
        REGEN_ASK: RT_REGEN_ASK, REGEN_CMD: RT_REGEN_CMD, SWIPE_CMD: RT_SWIPE_CMD, regenAllAsk: rtRegenAllAsk, swipes: rtSwipes };
})();

/* ===== 兜底条：最后一楼没出状态栏时的 ↻ =====
 *
 * 【病】↻「重试变量更新」只活在状态栏的 HTML 里，而状态栏是
 * 靠正文末尾那个 <StatusPlaceHolderImpl/> 触发正则渲染出来的。模型偶尔不写那个标记
 * （2026-09-21 实测：19 个有正文的楼里 2 次），那一楼就整条状态栏都没有，按钮点不到。
 * 偏偏漏写标记的往往也是 MVU 没跑成的那一楼，↻ 正是用来救它的。
 *
 * 【药】另开一条不依赖状态栏的路：主页面输入框上方长出一条小横条。
 * 只在**最后一楼是 AI 楼、却没有那个标记**时出现，状态栏正常时一个像素都不占。
 * 0 字楼（正文整个是空的）也归它管——那种楼同样没状态栏。
 *
 * 以前这条上还有 ▷「推进一轮」和 /推进 命令。2026-09-26 用户：不允许玩家不输入还能推进，
 * 推进一轮删了；▷ 只剩「推进 N 件」（随玩家下一条消息发，在状态栏里选），这条上不再放。
 *
 * 干活的还是原来的内核：window.XZ_RETRY（src/retry-core.js），和状态栏里的 ↻ 逐行同一份代码；
 * 「正在生成」借 window.XZ_OFFSTAGE（src/offstage-core.js）的 generating。
 *
 * 【挂在哪】这段跑在酒馆助手的脚本 iframe 里，DOM 得往 window.parent 里塞：
 * #sheld > #form_sheld 之前，也就是输入框正上方。不改酒馆本体，纯运行时 DOM。
 *
 * 【为什么还要轮询】显隐要跟着「最后一楼是谁、正文里有没有标记」走，这两样会被
 * 生成、删楼、swipe、编辑、/sendas……好几条路改到，挨个挂事件容易漏。所以一秒多扫一次，
 * 只在结论变了的时候才动 DOM。读的是内存里的 chat 数组，便宜。
 *
 * 【保底的保底】顺手注册 /重试变量 这条 slash 命令：横条万一没长出来
 * （酒馆改了 DOM、主题插件挪了位置），命令行还在。
 */
(function () {
    const RS_MARK = '<StatusPlaceHolderImpl/>';
    const RS_SCAN = 1200;

    const OS = window.XZ_OFFSTAGE;
    const RT = window.XZ_RETRY;

    const CSS = `
#xz-rescue {
    display: flex; align-items: center; gap: 8px;
    margin: 0 6px 4px; padding: 4px 8px;
    border: 1px solid var(--SmartThemeBorderColor, rgba(255,255,255,.2));
    border-radius: 8px;
    background: var(--SmartThemeBlurTintColor, rgba(0,0,0,.35));
    font-size: .88em; line-height: 1.6;
}
#xz-rescue .xz-why { flex: 1 1 auto; opacity: .6; }
#xz-rescue button {
    flex: 0 0 auto; padding: 2px 10px; border-radius: 6px; cursor: pointer;
    border: 1px solid var(--SmartThemeBorderColor, rgba(255,255,255,.25));
    background: transparent; color: inherit; font: inherit;
}
#xz-rescue button:hover:not(:disabled) { border-color: var(--SmartThemeQuoteColor, #c8a96a); }
#xz-rescue button:disabled { opacity: .38; cursor: default; }
#xz-rescue button[data-rt="ok"] { color: #6fbf73; }
#xz-rescue button[data-rt="bad"]:not(:disabled) { color: #cf6d6d; }
`;

    function doc() {
        try { return window.parent.document; } catch (e) { return null; }
    }

    function ensureStyle(d) {
        if (d.getElementById('xz-rescue-style')) return;
        const st = d.createElement('style');
        st.id = 'xz-rescue-style';
        st.textContent = CSS;
        d.head.appendChild(st);
    }

    /** 造那条横条（只造一次），返回它；位置没了就返回 null */
    function ensureBar() {
        const d = doc();
        if (!d) return null;
        let bar = d.getElementById('xz-rescue');
        if (bar && bar.isConnected) return bar;
        const sheld = d.getElementById('sheld');
        const form = d.getElementById('form_sheld');
        if (!sheld || !form) return null;
        ensureStyle(d);
        bar = d.createElement('div');
        bar.id = 'xz-rescue';
        bar.innerHTML = '<span class="xz-why">这一楼没出状态栏</span>'
            + '<button id="xz-rescue-rt" type="button">↻ 重试任务</button>';
        sheld.insertBefore(bar, form);
        bar.querySelector('#xz-rescue-rt').addEventListener('click', (e) => {
            e.preventDefault(); e.stopPropagation(); rt.click();
        });
        return bar;
    }

    function $bar() {
        const d = doc();
        return d ? d.getElementById('xz-rescue') : null;
    }

    /* ---------- 最后一楼长什么样 ---------- */

    function lastId() {
        try { return (SillyTavern.getContext().chat || []).length - 1; } catch (e) { return -1; }
    }

    /** 最后一楼是不是一条 AI 楼。第 0 楼是开局那一幕，不算——那一楼没有变量更新可重试。 */
    function rsAiLast() {
        try {
            const chat = SillyTavern.getContext().chat || [];
            const id = chat.length - 1;
            if (id < 1) return false;
            const m = chat[id];
            return !!m && !m.is_user && !m.is_system;
        } catch (e) { return false; }
    }

    /** 最后一楼正文里有没有那个占位标记（有 = 状态栏渲染得出来） */
    function rsHasMark() {
        try {
            const chat = SillyTavern.getContext().chat || [];
            const m = chat[chat.length - 1];
            return String((m && m.mes) || '').includes(RS_MARK);
        } catch (e) { return false; }
    }

    /** 横条该不该出现：最后一楼是 AI 楼、正文里没有那个占位标记，而且现在没在生成
     *  （生成中正文还没写完，标记本来就还没到，这会儿冒出来只会闪一下）。 */
    function rsNeeded() {
        return rsAiLast() && !OS.generating() && !rsHasMark();
    }

    /* ---------- ↻ ---------- */

    let rtState = 'bad', rtCan = false, rtTitle = '';
    const rt = RT.attach({
        floor: lastId,
        isLast: rsAiLast,            // 盯的就是最后一楼
        paint: (state, can, title) => { rtState = state; rtCan = can; rtTitle = title; rsPaintRetry(); },
    });

    function rsPaintRetry() {
        const bar = $bar();
        if (!bar) return;
        const b = bar.querySelector('#xz-rescue-rt');
        if (!b) return;
        b.dataset.rt = rtState;
        b.disabled = !rtCan;
        b.title = rtTitle;
        b.textContent = rtState === 'ok' ? '✓ 变量已更新'
            : rtState === 'wait' ? '↻ 变量更新中' : '↻ 重试任务';
    }

    /* ---------- 显隐 ---------- */

    let shown = null;

    function rsPaint() {
        const want = rsNeeded();
        if (want) {
            const bar = ensureBar();
            if (!bar) return;
            bar.style.display = '';
            if (shown !== true) rt.refresh();     // 刚冒出来，按这一楼的实际情况点灯
            rsPaintRetry();
        } else {
            const bar = $bar();
            if (bar) bar.style.display = 'none';
        }
        shown = want;
    }

    /* ---------- slash 保底 ---------- */

    function rsSlash() {
        let ctx;
        try { ctx = window.parent.SillyTavern.getContext(); } catch (e) { return; }
        const P = ctx.SlashCommandParser, C = ctx.SlashCommand;
        if (!P || !C || !P.commands) return;
        const add = (name, help, fn) => {
            if (P.commands[name]) return;         // 脚本重载过一次，别重复注册
            try { P.addCommandObject(C.fromProps({ name, callback: fn, helpString: help })); }
            catch (e) { console.error('[兜底条] 注册 /' + name + ' 失败', e); }
        };
        add('重试变量', '重试最后一楼的状态更新（独立 API：只重跑变量更新，不重写正文；随正文：确认后重新生成这一楼）',
            async () => { await rt.click(); return ''; });
    }

    /* ---------- 起 ---------- */

    try {
        rsSlash();
        rsPaint();
        setInterval(rsPaint, RS_SCAN);
        OS.onChange(rsPaint);
        for (const ev of ['GENERATION_STARTED', 'GENERATION_ENDED', 'GENERATION_STOPPED',
            'MESSAGE_RECEIVED', 'MESSAGE_DELETED', 'MESSAGE_EDITED', 'MESSAGE_SWIPED',
            'CHAT_CHANGED']) {
            try { eventOn(tavern_events[ev], rsPaint); } catch (e) { }
        }
        // 卡被换掉时这个 iframe 会没，横条是塞在主页面里的，得自己带走
        const bye = () => { const b = $bar(); if (b) b.remove(); };
        window.addEventListener('pagehide', bye);
        window.addEventListener('unload', bye);
    } catch (e) {
        console.error('[兜底条] 起不来', e);
    }

    // 离线测试床用的出口（node 里跑显隐和点击，见 test_canon.mjs）。真机上没人读它。
    try { window.__xzRescue = { rsNeeded, rsAiLast, rsHasMark, rsPaint, bar: $bar }; } catch (e) { }
})();
// xz-prompt-providers:start
// Existing editors and this menu share the same stores, avoiding shadow copies.
(function(){
    const host=window.parent?.SillyTavern?window.parent:window;
    const api=host.XZ_PROMPTS,context=()=>SillyTavern.getContext(),owner=context().characters?.[context().characterId]?.avatar;
    if(!api)return;
    const SID='c0a17e6d-9b4f-4d21-8f3a-7e15cbb20d91';
    const story=()=>window.XZ_STORY.create(TavernHelper,context);
    const slotNames={head:'资料区之前 · system',link:'聊天记录之前 · system',prefill:'回复开头预填 · assistant'};
    const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
    const options={type:'script',script_id:SID};
    async function sync(){
        const existing=TavernHelper.getPresetNames();
        for(const it of mcLoad(SID).s.items){
            const name=mcPresetName(it.name);if(!existing.includes(name))continue;
            await eventEmit('XZ_MVU_JB_CUSTOM',it.id);
            const pick=rows=>rows.map(p=>[p.id,p.content||'']);
            if(!same(pick(TavernHelper.getPreset(name).prompts),pick(mcPrompts(it))))throw Error('提示词已保存，但 MVU 预设尚未同步，请保留页面并重试');
        }
    }
    api.provider(owner,{
        list(){
            const cfg=story().readConfig();
            const profile=TavernHelper.getVariables({type:'chat'})?.xz_player_profile;
            return [{id:'story.prompt',external:'story',group:'剧情素材',title:'素材注入说明',position:'正文 · user · 聊天深度 1 · 所选素材前',condition:'本轮启用剧情素材时',scope:'当前聊天',params:[],value:cfg.prompt,text:window.XZ_STORY.DEFAULT_PROMPT,custom:cfg.prompt!==window.XZ_STORY.DEFAULT_PROMPT},
            ...(profile?.v===1&&typeof profile.content==='string'?[{id:'player.profile',external:'player',group:'本局主角人设',title:'本局主角人设与行为边界',position:'正文 · 前置系统消息',condition:'本局已有开局人设时',scope:'当前聊天（只改提示词，不改状态变量）',params:[],value:profile.content,custom:true}]:[]),
            ...mcLoad(SID).s.items.flatMap(it=>['head','link','prefill'].map(slot=>({id:'mvu.profile.'+it.id+'.'+slot,external:'mvu',item:it.id,slot,group:'MVU 预设',title:it.name+' · '+slotNames[slot].split(' · ')[0],position:'MVU 更新 · '+slotNames[slot],condition:'MVU 选中「'+it.name+'」时',scope:'本书 MVU 配置',params:[],value:it[slot],text:MC.defaults.find(d=>d.id===it.id)?.[slot],custom:true})))];
        },sync,
        async save(e,text,expected,s,check){
            check(s);
            if(e.external==='player'){
                await TavernHelper.updateVariablesWith(bag=>{check(s);if(bag?.xz_player_profile?.content!==expected)throw Error('本局人设已变化，请重新载入');return {...bag,xz_player_profile:{...bag.xz_player_profile,content:text}};},{type:'chat'});
                check(s);await context().saveMetadata();check(s);
                if(TavernHelper.getVariables({type:'chat'})?.xz_player_profile?.content!==text)throw Error('本局人设回读失败');return;
            }
            if(e.external==='story'){
                const store=story(),before=store.readConfig();if(before.prompt!==expected)throw Error('素材提示词已变化，请重新载入');
                await store.saveConfig({...before,prompt:text},store.scope());check(s);
                if(store.readConfig().prompt!==text)throw Error('素材提示词回读失败');return;
            }
            const before=mcLoad(SID).s,it=mcFind(before,e.item);if(!it||it[e.slot]!==expected)throw Error('MVU 配置已变化，请重新载入');
            const result=mcUpsert(before,{...it,[e.slot]:text});if(result.err)throw Error(result.err);
            const server=await api.disk(s);check(s);
            const diskScript=server.data.extensions.tavern_helper.scripts.find(x=>x.id===SID);
            if(!same(mcWithDefaults(mcNorm(diskScript?.data?.[MC.key])||mcNorm(server.data.extensions[MC.ext])),before))throw Error('服务器 MVU 配置已变化，请重新载入');
            await TavernHelper.updateVariablesWith(bag=>{check(s);if(!same(mcWithDefaults(mcNorm(bag?.[MC.key])||mcFromCard()),before))throw Error('MVU 配置已变化');return {...bag,[MC.key]:result.s};},options);check(s);
            await context().writeExtensionField(context().characterId,MC.ext,{...result.s,synced:new Date().toISOString()});check(s);
            const saved=await api.disk(s);check(s);
            if(!same(mcNorm(saved.data.extensions[MC.ext]),result.s)||!same(saved.data.extensions.tavern_helper.scripts.find(x=>x.id===SID)?.data?.[MC.key],result.s))throw Error('MVU 配置尚未确认保存，请保留草稿');
            await eventEmit('XZ_MVU_JB_CUSTOM',e.item);check(s);
            const expectedPrompts=mcPrompts(result.item),actual=TavernHelper.getPreset(mcPresetName(result.item.name)).prompts;
            if(!same(actual.map(p=>[p.id,p.content||'']),expectedPrompts.map(p=>[p.id,p.content||''])))throw Error('配置已保存，MVU 预设尚未同步，请在 API 设置中重新保存');
        }
    });
})();

// xz-prompt-providers:end